// 历史人物（中英双语）· Famous people (bilingual). at: related city ids, first = main place; c/pl: birthplace when not a city on the map
window.PEOPLE=[
// ---- Ancient Near East & Mediterranean ----
{id:"hammurabi",y:[-1810,-1750],ca:1,at:["babylon"],n:{zh:"汉谟拉比",en:"Hammurabi"},r:{zh:"巴比伦国王",en:"King of Babylon"},d:{zh:"古巴比伦第一王朝的国王，统一了美索不达米亚南部，颁布了现存最完整的古代法典之一《汉谟拉比法典》。",en:"King of the First Babylonian Dynasty who united southern Mesopotamia and issued the Code of Hammurabi, one of the most complete ancient law codes to survive."}},
{id:"ramesses-ii",y:[-1303,-1213],ca:1,at:["thebes"],n:{zh:"拉美西斯二世",en:"Ramesses II"},r:{zh:"埃及法老",en:"Pharaoh of Egypt"},d:{zh:"新王国第十九王朝的法老，在位六十余年，与赫梯人在卡迭石交战后签订了已知最早的和约之一，修建了阿布辛贝神庙。",en:"Pharaoh of the Nineteenth Dynasty who reigned for more than sixty years, fought the Hittites at Kadesh and later made one of the earliest known peace treaties with them, and built Abu Simbel."}},
{id:"tutankhamun",y:[-1341,-1323],ca:1,at:["thebes"],n:{zh:"图坦卡蒙",en:"Tutankhamun"},r:{zh:"埃及法老",en:"Pharaoh of Egypt"},d:{zh:"第十八王朝的少年法老，恢复了阿蒙神崇拜；1922 年其几乎完好的陵墓在帝王谷被发现。",en:"Boy pharaoh of the Eighteenth Dynasty who restored the worship of Amun; his almost intact tomb was found in the Valley of the Kings in 1922."}},
{id:"ashurbanipal",y:[-685,-631],ca:1,at:["nineveh"],n:{zh:"亚述巴尼拔",en:"Ashurbanipal"},r:{zh:"亚述国王",en:"King of Assyria"},d:{zh:"亚述帝国最后一位强大的君主，在尼尼微建立了收藏数万块泥板的图书馆，《吉尔伽美什史诗》因此得以保存。",en:"The last great king of Assyria, who gathered a library of tens of thousands of clay tablets at Nineveh, preserving among them the Epic of Gilgamesh."}},
{id:"nebuchadnezzar-ii",y:[-634,-562],ca:1,at:["babylon","jerusalem"],n:{zh:"尼布甲尼撒二世",en:"Nebuchadnezzar II"},r:{zh:"新巴比伦国王",en:"King of Babylon"},d:{zh:"新巴比伦王国最强盛的君主，攻灭犹大王国、焚毁耶路撒冷圣殿，并大规模营建巴比伦城与伊什塔尔城门。",en:"The most powerful king of the Neo-Babylonian Empire, who destroyed the kingdom of Judah and the Temple in Jerusalem and rebuilt Babylon with the Ishtar Gate."}},
{id:"cyrus-the-great",y:[-600,-530],ca:1,at:["babylon"],c:[53.17,30.20],pl:{en:"Pasargadae",zh:"帕萨尔加德"},n:{zh:"居鲁士大帝",en:"Cyrus the Great"},r:{zh:"波斯阿契美尼德帝国创建者",en:"Founder of the Achaemenid Persian Empire"},d:{zh:"击败米底、吕底亚与巴比伦，建立了当时世界上最大的帝国；他允许被掳的犹太人返回故土。",en:"Conquered Media, Lydia and Babylon to build the largest empire the world had yet seen, and allowed the exiled Judeans to return home."}},
{id:"darius-i",y:[-550,-486],at:["babylon"],c:[52.89,29.93],pl:{en:"Persepolis",zh:"波斯波利斯"},n:{zh:"大流士一世",en:"Darius I"},r:{zh:"波斯国王",en:"King of Persia"},d:{zh:"阿契美尼德帝国的组织者，设立行省、修筑御道、统一货币，兴建波斯波利斯，并发动了第一次希波战争。",en:"Organiser of the Achaemenid Empire who created satrapies, built the Royal Road, standardised coinage, founded Persepolis and launched the first Persian invasion of Greece."}},
{id:"pericles",y:[-495,-429],at:["athens"],n:{zh:"伯里克利",en:"Pericles"},r:{zh:"雅典政治家",en:"Athenian statesman"},d:{zh:"雅典民主鼎盛时期的领袖，主持修建帕特农神庙，伯罗奔尼撒战争初期死于瘟疫。",en:"Leader of Athens at the height of its democracy who rebuilt the Acropolis with the Parthenon; he died of the plague early in the Peloponnesian War."}},
{id:"herodotus",y:[-484,-425],ca:1,at:["athens"],c:[27.43,37.04],pl:{en:"Halicarnassus",zh:"哈利卡纳苏斯"},n:{zh:"希罗多德",en:"Herodotus"},r:{zh:"历史学家",en:"Historian"},d:{zh:"被称为“历史之父”，其《历史》记述了希波战争以及他游历所见的各地风俗。",en:"Called the ‘Father of History’; his Histories tell the story of the Persian Wars and describe the peoples he met on his travels."}},
{id:"socrates",y:[-470,-399],at:["athens"],n:{zh:"苏格拉底",en:"Socrates"},r:{zh:"哲学家",en:"Philosopher"},d:{zh:"雅典哲学家，以对话诘问探求伦理问题，未留下著作；被控“不敬神、腐蚀青年”，饮毒芹而死。",en:"Athenian philosopher who questioned his fellow citizens about how to live; he wrote nothing and was condemned to drink hemlock for impiety and corrupting the young."}},
{id:"plato",y:[-428,-348],ca:1,at:["athens","syracuse"],n:{zh:"柏拉图",en:"Plato"},r:{zh:"哲学家",en:"Philosopher"},d:{zh:"苏格拉底的学生，在雅典创办学园，以对话体写成《理想国》等著作，曾三次前往叙拉古。",en:"Pupil of Socrates who founded the Academy in Athens and wrote dialogues such as the Republic; he made three journeys to Syracuse."}},
{id:"aristotle",y:[-384,-322],at:["athens"],c:[23.77,40.53],pl:{en:"Stagira",zh:"斯塔吉拉"},n:{zh:"亚里士多德",en:"Aristotle"},r:{zh:"哲学家",en:"Philosopher"},d:{zh:"柏拉图的学生、亚历山大大帝的老师，在雅典创办吕克昂学园，著述涵盖逻辑、伦理、政治与自然科学。",en:"Pupil of Plato and tutor of Alexander the Great who founded the Lyceum in Athens and wrote on logic, ethics, politics and the natural world."}},
{id:"alexander-the-great",y:[-356,-323],at:["babylon","alexandria","tyre"],c:[22.52,40.76],pl:{en:"Pella",zh:"佩拉"},n:{zh:"亚历山大大帝",en:"Alexander the Great"},r:{zh:"马其顿国王",en:"King of Macedon"},d:{zh:"二十岁继承马其顿王位，十余年间征服波斯帝国直至印度河，建立多座亚历山大城，三十二岁死于巴比伦。",en:"King of Macedon at twenty who conquered the Persian Empire as far as the Indus within a decade, founded many Alexandrias and died at Babylon aged thirty-two."}},
{id:"euclid",y:[-325,-265],ca:1,at:["alexandria"],n:{zh:"欧几里得",en:"Euclid"},r:{zh:"数学家",en:"Mathematician"},d:{zh:"亚历山大城的数学家，所著《几何原本》以公理推导定理，两千年来一直是几何学的标准教材。",en:"Mathematician of Alexandria whose Elements derived geometry from axioms and remained the standard textbook for two thousand years."}},
{id:"archimedes",y:[-287,-212],ca:1,at:["syracuse","alexandria"],n:{zh:"阿基米德",en:"Archimedes"},r:{zh:"数学家、发明家",en:"Mathematician and inventor"},d:{zh:"叙拉古的数学家和工程师，发现浮力原理并计算圆周率近似值；罗马攻陷叙拉古时被杀。",en:"Mathematician and engineer of Syracuse who discovered the principle of buoyancy and estimated pi; he was killed when Rome took the city."}},
{id:"hannibal",y:[-247,-183],ca:1,at:["carthage"],n:{zh:"汉尼拔",en:"Hannibal"},r:{zh:"迦太基统帅",en:"Carthaginian general"},d:{zh:"第二次布匿战争中率军翻越阿尔卑斯山进入意大利，在坎尼大胜罗马，最终在扎马战败。",en:"Led an army across the Alps into Italy in the Second Punic War and crushed Rome at Cannae, but was finally defeated at Zama."}},
{id:"cicero",y:[-106,-43],at:["rome"],n:{zh:"西塞罗",en:"Cicero"},r:{zh:"演说家、政治家",en:"Orator and statesman"},d:{zh:"罗马共和国晚期最著名的演说家和文体家，反对凯撒与安东尼，在后三头同盟的清洗中被杀。",en:"The greatest orator and prose stylist of the late Roman Republic; he opposed Caesar and Antony and was killed in the proscriptions of the Second Triumvirate."}},
{id:"julius-caesar",y:[-100,-44],at:["rome","alexandria"],n:{zh:"尤利乌斯·凯撒",en:"Julius Caesar"},r:{zh:"罗马统帅、独裁官",en:"Roman general and dictator"},d:{zh:"征服高卢后渡过卢比孔河发动内战，成为终身独裁官，公元前 44 年 3 月 15 日在元老院遇刺。",en:"Conquered Gaul, crossed the Rubicon to win a civil war and became dictator for life; he was assassinated in the Senate on the Ides of March, 44 BC."}},
{id:"virgil",y:[-70,-19],at:["rome","naples"],n:{zh:"维吉尔",en:"Virgil"},r:{zh:"诗人",en:"Poet"},d:{zh:"奥古斯都时代的罗马诗人，史诗《埃涅阿斯纪》讲述罗马的起源，葬于那不勒斯。",en:"Roman poet of the Augustan age whose epic, the Aeneid, tells the legendary origins of Rome; he was buried at Naples."}},
{id:"cleopatra",y:[-69,-30],at:["alexandria","rome"],n:{zh:"克娄巴特拉七世",en:"Cleopatra VII"},r:{zh:"埃及女王",en:"Queen of Egypt"},d:{zh:"托勒密王朝末代女王，先后与凯撒和安东尼结盟；亚克兴战败后自尽，埃及并入罗马。",en:"Last ruler of Ptolemaic Egypt, allied in turn with Caesar and Mark Antony; after defeat at Actium she took her own life and Egypt became Roman."}},
{id:"augustus",y:[-63,14],at:["rome"],n:{zh:"奥古斯都",en:"Augustus"},r:{zh:"罗马第一位皇帝",en:"First Roman emperor"},d:{zh:"凯撒的养子，击败安东尼后建立元首制，开启两百年的“罗马和平”。",en:"Caesar’s adopted heir who defeated Antony, founded the Principate and began two centuries of the Pax Romana."}},
{id:"jesus",y:[-4,30],ca:1,at:["jerusalem"],c:[35.30,32.70],pl:{en:"Nazareth",zh:"拿撒勒"},n:{zh:"耶稣",en:"Jesus of Nazareth"},r:{zh:"基督教的核心人物",en:"Central figure of Christianity"},d:{zh:"加利利的犹太传道者，在罗马总督彼拉多治下于耶路撒冷被钉十字架；其追随者形成了基督教。",en:"Jewish preacher from Galilee who was crucified in Jerusalem under the Roman governor Pontius Pilate; his followers founded Christianity."}},
{id:"ptolemy",y:[100,170],ca:1,at:["alexandria"],n:{zh:"托勒密",en:"Ptolemy"},r:{zh:"天文学家、地理学家",en:"Astronomer and geographer"},d:{zh:"亚历山大城的学者，《天文学大成》中的地心体系影响欧洲与伊斯兰世界一千四百年，《地理学》以经纬度标注地名。",en:"Scholar of Alexandria whose geocentric Almagest shaped astronomy in Europe and the Islamic world for fourteen centuries; his Geography listed places by latitude and longitude."}},
{id:"marcus-aurelius",y:[121,180],at:["rome","vienna"],n:{zh:"马可·奥勒留",en:"Marcus Aurelius"},r:{zh:"罗马皇帝、哲学家",en:"Roman emperor and philosopher"},d:{zh:"“五贤帝”中的最后一位，晚年在多瑙河前线作战，写下斯多葛派的《沉思录》，死于文多博纳（今维也纳）一带。",en:"Last of the ‘Five Good Emperors’, who spent his later years fighting on the Danube and wrote the Stoic Meditations; he died at or near Vindobona (Vienna)."}},
{id:"constantine-the-great",y:[272,337],at:["istanbul","trier","york"],n:{zh:"君士坦丁大帝",en:"Constantine the Great"},r:{zh:"罗马皇帝",en:"Roman emperor"},d:{zh:"在约克被拥立为帝，在米尔维安桥战胜对手，颁布宽容基督教的《米兰敕令》，并将首都迁至君士坦丁堡。",en:"Proclaimed emperor at York, he won at the Milvian Bridge, granted toleration to Christians and moved the capital to Constantinople."}},
{id:"augustine",y:[354,430],at:["carthage","milan","rome"],c:[7.95,36.29],pl:{en:"Thagaste",zh:"塔加斯特"},n:{zh:"奥古斯丁",en:"Augustine of Hippo"},r:{zh:"神学家",en:"Theologian"},d:{zh:"北非出生的神学家，在米兰皈依基督教，后任希波主教，《忏悔录》与《上帝之城》深刻影响了西方思想。",en:"North African theologian who converted in Milan and became Bishop of Hippo; his Confessions and City of God shaped Western thought."}},
{id:"hypatia",y:[355,415],ca:1,at:["alexandria"],n:{zh:"希帕提娅",en:"Hypatia"},r:{zh:"哲学家、数学家",en:"Philosopher and mathematician"},d:{zh:"亚历山大城的新柏拉图派学者，讲授数学与天文学，在城中宗教与政治冲突中被暴徒杀害。",en:"Neoplatonist scholar of Alexandria who taught mathematics and astronomy; she was murdered by a mob amid the city’s religious and political strife."}},
{id:"justinian",y:[482,565],at:["istanbul","ravenna"],n:{zh:"查士丁尼一世",en:"Justinian I"},r:{zh:"拜占庭皇帝",en:"Byzantine emperor"},d:{zh:"编纂《罗马民法大全》，重建圣索菲亚大教堂，并收复北非与意大利。",en:"Codified Roman law in the Corpus Juris Civilis, rebuilt Hagia Sophia and reconquered North Africa and Italy."}},
// ---- Islamic world ----
{id:"muhammad",y:[570,632],ca:1,at:["mecca","medina"],n:{zh:"穆罕默德",en:"Muhammad"},r:{zh:"伊斯兰教先知",en:"Prophet of Islam"},d:{zh:"生于麦加，622 年迁往麦地那，此后统一阿拉伯半岛大部，是伊斯兰教的创立者。",en:"Born in Mecca, he moved to Medina in 622 and went on to unite most of Arabia; Muslims regard him as the final prophet of Islam."}},
{id:"harun-al-rashid",y:[763,809],ca:1,at:["baghdad"],n:{zh:"哈伦·拉希德",en:"Harun al-Rashid"},r:{zh:"阿拔斯王朝哈里发",en:"Abbasid caliph"},d:{zh:"阿拔斯王朝鼎盛时期的哈里发，巴格达成为世界性的大都市，《一千零一夜》中多有他的故事。",en:"Abbasid caliph at the height of the dynasty, when Baghdad became a world city; he appears in many tales of the Thousand and One Nights."}},
{id:"al-khwarizmi",y:[780,850],ca:1,at:["baghdad"],n:{zh:"花拉子米",en:"al-Khwarizmi"},r:{zh:"数学家",en:"Mathematician"},d:{zh:"巴格达智慧宫的学者，其著作奠定了代数学，“算法”一词即源于他的名字，并将印度数字传入伊斯兰世界与欧洲。",en:"Scholar of the House of Wisdom in Baghdad whose book founded algebra; the word ‘algorithm’ comes from his name, and he spread Indian numerals to the Islamic world and Europe."}},
{id:"avicenna",y:[980,1037],at:["bukhara","isfahan"],n:{zh:"伊本·西那",en:"Avicenna (Ibn Sina)"},r:{zh:"医学家、哲学家",en:"Physician and philosopher"},d:{zh:"生于布哈拉附近，所著《医典》在欧洲与伊斯兰世界被用作医学教科书达数百年。",en:"Born near Bukhara, he wrote the Canon of Medicine, used as a medical textbook in the Islamic world and Europe for centuries."}},
{id:"averroes",y:[1126,1198],at:["cordoba","marrakesh"],n:{zh:"伊本·鲁世德",en:"Averroes (Ibn Rushd)"},r:{zh:"哲学家",en:"Philosopher"},d:{zh:"科尔多瓦的哲学家和法官，为亚里士多德著作作注，对中世纪欧洲经院哲学影响深远。",en:"Philosopher and judge of Córdoba whose commentaries on Aristotle deeply influenced medieval European scholasticism."}},
{id:"maimonides",y:[1138,1204],at:["cordoba","fez","cairo"],n:{zh:"迈蒙尼德",en:"Maimonides"},r:{zh:"犹太哲学家、医生",en:"Jewish philosopher and physician"},d:{zh:"生于科尔多瓦，因迫害迁居非斯、开罗，任萨拉丁宫廷医生，著有《迷途指津》。",en:"Born in Córdoba, he fled persecution to Fez and Cairo, became court physician to Saladin’s household and wrote the Guide for the Perplexed."}},
{id:"saladin",y:[1137,1193],at:["damascus","cairo","jerusalem"],c:[43.68,34.60],pl:{en:"Tikrit",zh:"提克里特"},n:{zh:"萨拉丁",en:"Saladin"},r:{zh:"埃及与叙利亚苏丹",en:"Sultan of Egypt and Syria"},d:{zh:"阿尤布王朝的创立者，1187 年在哈丁战胜十字军并收复耶路撒冷，葬于大马士革。",en:"Founder of the Ayyubid dynasty who defeated the Crusaders at Hattin in 1187 and retook Jerusalem; he is buried in Damascus."}},
{id:"saadi",y:[1210,1291],ca:1,at:["shiraz","baghdad"],n:{zh:"萨迪",en:"Saadi"},r:{zh:"诗人",en:"Poet"},d:{zh:"设拉子的波斯诗人，游历中东数十年后写成《果园》与《蔷薇园》。",en:"Persian poet of Shiraz who travelled the Middle East for decades and wrote the Bustan and the Gulistan."}},
{id:"rumi",y:[1207,1273],at:["konya"],c:[66.90,36.76],pl:{en:"Balkh",zh:"巴尔赫"},n:{zh:"鲁米",en:"Rumi"},r:{zh:"诗人、苏菲派神秘主义者",en:"Poet and Sufi mystic"},d:{zh:"生于巴尔赫，为躲避蒙古西迁至科尼亚，其波斯语长诗《玛斯纳维》被誉为苏菲派经典；旋转舞僧团奉他为祖师。",en:"Born in Balkh, he fled the Mongols to Konya; his Persian Masnavi is a classic of Sufism, and the whirling dervishes trace their order to him."}},
{id:"ibn-battuta",y:[1304,1369],at:["fez","delhi","quanzhou","kilwa"],c:[-5.80,35.77],pl:{en:"Tangier",zh:"丹吉尔"},n:{zh:"伊本·白图泰",en:"Ibn Battuta"},r:{zh:"旅行家",en:"Traveller"},d:{zh:"出生于丹吉尔，近三十年间游历非洲、中东、印度与中国，行程逾十万公里，回国后在非斯口述游记。",en:"Born in Tangier, he spent almost thirty years travelling through Africa, the Middle East, India and China, more than 100,000 km, and dictated his travels in Fez."}},
{id:"hafez",y:[1315,1390],ca:1,at:["shiraz"],n:{zh:"哈菲兹",en:"Hafez"},r:{zh:"诗人",en:"Poet"},d:{zh:"设拉子的波斯抒情诗人，其诗集至今在伊朗家家收藏，常被用来占卜。",en:"Lyric poet of Shiraz whose collected poems are still found in almost every Iranian home and are used for divination."}},
{id:"ibn-khaldun",y:[1332,1406],at:["cairo","fez","damascus"],c:[10.17,36.80],pl:{en:"Tunis",zh:"突尼斯"},n:{zh:"伊本·赫勒敦",en:"Ibn Khaldun"},r:{zh:"历史学家",en:"Historian"},d:{zh:"生于突尼斯，所著《历史绪论》分析王朝兴衰与社会凝聚力，被视为社会学与史学理论的先驱；曾在大马士革城外会见帖木儿。",en:"Born in Tunis, he wrote the Muqaddimah on the rise and fall of dynasties, a forerunner of sociology; he met Timur outside Damascus."}},
{id:"timur",y:[1336,1405],at:["samarkand","delhi","damascus","ankara"],n:{zh:"帖木儿",en:"Timur (Tamerlane)"},r:{zh:"帖木儿帝国创建者",en:"Founder of the Timurid Empire"},d:{zh:"从河中地区崛起，征战波斯、印度、叙利亚与安纳托利亚，在安卡拉俘获奥斯曼苏丹巴耶济德一世，以撒马尔罕为都。",en:"Rose in Transoxiana and campaigned through Persia, India, Syria and Anatolia, capturing the Ottoman sultan Bayezid I at Ankara; Samarkand was his capital."}},
{id:"ulugh-beg",y:[1394,1449],at:["samarkand"],n:{zh:"兀鲁伯",en:"Ulugh Beg"},r:{zh:"天文学家、君主",en:"Astronomer and ruler"},d:{zh:"帖木儿之孙，在撒马尔罕修建天文台，编制的星表是托勒密之后最精确的一部。",en:"Grandson of Timur who built an observatory at Samarkand; his star catalogue was the most accurate since Ptolemy."}},
{id:"mehmed-ii",y:[1432,1481],at:["edirne","istanbul"],n:{zh:"穆罕默德二世",en:"Mehmed II"},r:{zh:"奥斯曼苏丹",en:"Ottoman sultan"},d:{zh:"生于埃迪尔内，1453 年攻陷君士坦丁堡，终结拜占庭帝国，并将其定为奥斯曼新都。",en:"Born in Edirne, he took Constantinople in 1453, ending the Byzantine Empire, and made it the new Ottoman capital."}},
{id:"suleiman",y:[1494,1566],at:["trabzon","istanbul","budapest","vienna"],n:{zh:"苏莱曼一世",en:"Suleiman the Magnificent"},r:{zh:"奥斯曼苏丹",en:"Ottoman sultan"},d:{zh:"生于特拉布宗，在位期间奥斯曼帝国达到鼎盛，攻取贝尔格莱德与布达，围攻维也纳，并编订法典。",en:"Born in Trabzon, he led the Ottoman Empire at its height, took Belgrade and Buda, besieged Vienna and reformed the law."}},
{id:"shah-abbas",y:[1571,1629],at:["isfahan"],n:{zh:"阿拔斯一世",en:"Shah Abbas I"},r:{zh:"萨法维王朝君主",en:"Safavid shah"},d:{zh:"萨法维王朝最杰出的君主，夺回被奥斯曼占领的领土，迁都伊斯法罕并营建伊玛目广场。",en:"The greatest Safavid ruler, who won back land from the Ottomans, moved the capital to Isfahan and built its great square."}},
{id:"muhammad-ali-pasha",y:[1769,1849],at:["cairo","alexandria"],c:[24.41,40.94],pl:{en:"Kavala",zh:"卡瓦拉"},n:{zh:"穆罕默德·阿里",en:"Muhammad Ali Pasha"},r:{zh:"埃及总督",en:"Ruler of Egypt"},d:{zh:"奥斯曼帝国的埃及总督，推行军事和经济改革，被视为现代埃及的奠基者。",en:"Ottoman governor of Egypt whose military and economic reforms made him the founder of modern Egypt."}},
{id:"ataturk",y:[1881,1938],at:["thessaloniki","ankara","istanbul"],n:{zh:"穆斯塔法·凯末尔·阿塔图尔克",en:"Mustafa Kemal Atatürk"},r:{zh:"土耳其共和国创建者",en:"Founder of the Republic of Turkey"},d:{zh:"生于萨洛尼卡，加里波利战役中成名，领导独立战争后建立土耳其共和国，定都安卡拉并推行世俗化改革。",en:"Born in Salonica, he made his name at Gallipoli, led the War of Independence and founded the Turkish Republic with Ankara as capital, introducing secular reforms."}},
{id:"nasser",y:[1918,1970],at:["alexandria","cairo"],n:{zh:"纳赛尔",en:"Gamal Abdel Nasser"},r:{zh:"埃及总统",en:"President of Egypt"},d:{zh:"1952 年自由军官革命的领导者，1956 年将苏伊士运河收归国有，是阿拉伯民族主义的代表人物。",en:"Leader of the Free Officers’ revolution of 1952 who nationalised the Suez Canal in 1956 and became the figurehead of Arab nationalism."}},
// ---- Medieval & early modern Europe ----
{id:"charlemagne",y:[742,814],ca:1,at:["aachen","rome"],n:{zh:"查理曼",en:"Charlemagne"},r:{zh:"法兰克国王、皇帝",en:"King of the Franks and emperor"},d:{zh:"统一西欧大部，800 年圣诞节在罗马由教皇加冕为皇帝，以亚琛为都推动“加洛林文艺复兴”。",en:"United most of western Europe and was crowned emperor by the pope in Rome on Christmas Day 800; from Aachen he fostered the Carolingian Renaissance."}},
{id:"alfred-the-great",y:[849,899],at:["london","york"],c:[-1.31,51.06],pl:{en:"Winchester",zh:"温切斯特"},n:{zh:"阿尔弗雷德大王",en:"Alfred the Great"},r:{zh:"威塞克斯国王",en:"King of Wessex"},d:{zh:"抵御维京大军，重建伦敦并修筑设防城镇，推动以古英语翻译典籍。",en:"Held off the Viking Great Army, refounded London, built a network of fortified towns and promoted translation into Old English."}},
{id:"william-the-conqueror",y:[1028,1087],at:["london","york"],c:[-0.42,48.89],pl:{en:"Falaise",zh:"法莱斯"},n:{zh:"征服者威廉",en:"William the Conqueror"},r:{zh:"英格兰国王",en:"King of England"},d:{zh:"诺曼底公爵，1066 年在黑斯廷斯战役中获胜，成为英格兰国王，下令编纂《末日审判书》。",en:"Duke of Normandy who won the Battle of Hastings in 1066, became King of England and ordered the Domesday survey."}},
{id:"el-cid",y:[1043,1099],ca:1,at:["valencia","toledo"],n:{zh:"熙德",en:"El Cid"},r:{zh:"卡斯蒂利亚骑士",en:"Castilian knight"},d:{zh:"罗德里戈·迪亚斯，卡斯蒂利亚贵族，曾为基督徒和穆斯林君主效力，1094 年攻取巴伦西亚并统治至死。",en:"Rodrigo Díaz, a Castilian noble who served both Christian and Muslim rulers; he took Valencia in 1094 and ruled it until his death."}},
{id:"frederick-ii",y:[1194,1250],at:["palermo","naples"],n:{zh:"腓特烈二世",en:"Frederick II"},r:{zh:"神圣罗马皇帝、西西里国王",en:"Holy Roman Emperor and King of Sicily"},d:{zh:"在巴勒莫长大，通晓多种语言，创办那不勒斯大学，以谈判方式收回耶路撒冷，与教皇长期对立。",en:"Raised in Palermo and fluent in several languages, he founded the University of Naples, regained Jerusalem by treaty and fought a long struggle with the papacy."}},
{id:"thomas-aquinas",y:[1225,1274],at:["naples","paris"],n:{zh:"托马斯·阿奎那",en:"Thomas Aquinas"},r:{zh:"神学家",en:"Theologian"},d:{zh:"多明我会修士，在巴黎与那不勒斯讲学，《神学大全》将亚里士多德哲学与基督教神学结合。",en:"Dominican friar who taught in Paris and Naples; his Summa Theologiae joined Aristotle’s philosophy to Christian theology."}},
{id:"marco-polo",y:[1254,1324],at:["venice","beijing","quanzhou","genoa"],n:{zh:"马可·波罗",en:"Marco Polo"},r:{zh:"商人、旅行家",en:"Merchant and traveller"},d:{zh:"威尼斯商人，随父辈经丝绸之路到达元朝，在忽必烈治下生活约十七年，其游记让欧洲认识了东方。",en:"Venetian merchant who travelled the Silk Road to Yuan China and spent some seventeen years under Kublai Khan; his book introduced Asia to Europe."}},
{id:"dante",y:[1265,1321],at:["florence","ravenna"],n:{zh:"但丁",en:"Dante Alighieri"},r:{zh:"诗人",en:"Poet"},d:{zh:"佛罗伦萨诗人，因政争被放逐，在流亡中写成以托斯卡纳方言创作的《神曲》，卒于拉文纳。",en:"Florentine poet exiled in a political feud, who wrote the Divine Comedy in Tuscan in exile and died in Ravenna."}},
{id:"giotto",y:[1267,1337],ca:1,at:["florence"],n:{zh:"乔托",en:"Giotto"},r:{zh:"画家、建筑师",en:"Painter and architect"},d:{zh:"以写实的人物与空间感打破拜占庭画风，被视为文艺复兴绘画的先驱，设计了佛罗伦萨大教堂钟楼。",en:"Broke with the Byzantine style through lifelike figures and space, a forerunner of Renaissance painting; he designed the bell tower of Florence Cathedral."}},
{id:"petrarch",y:[1304,1374],at:["avignon","florence"],c:[11.88,43.46],pl:{en:"Arezzo",zh:"阿雷佐"},n:{zh:"彼特拉克",en:"Petrarch"},r:{zh:"诗人、人文主义者",en:"Poet and humanist"},d:{zh:"在阿维尼翁教廷长大，以献给劳拉的十四行诗闻名，搜集古典手稿，被称为“人文主义之父”。",en:"Grew up at the papal court in Avignon; famous for his sonnets to Laura and his search for classical manuscripts, he is called the father of humanism."}},
{id:"jan-hus",y:[1372,1415],ca:1,at:["prague"],n:{zh:"扬·胡斯",en:"Jan Hus"},r:{zh:"宗教改革家",en:"Church reformer"},d:{zh:"布拉格大学校长，批评教会腐败，在康斯坦茨公会议上被判为异端并处以火刑，引发胡斯战争。",en:"Rector of Prague University who attacked church corruption; condemned as a heretic at the Council of Constance and burned, his death set off the Hussite Wars."}},
{id:"joan-of-arc",y:[1412,1431],ca:1,at:["reims","paris"],c:[5.67,48.44],pl:{en:"Domrémy",zh:"栋雷米"},n:{zh:"圣女贞德",en:"Joan of Arc"},r:{zh:"法国民族英雄",en:"French national heroine"},d:{zh:"农家少女，百年战争中解奥尔良之围，护送查理七世在兰斯加冕，后被英国人以异端罪名处以火刑。",en:"Peasant girl who raised the siege of Orléans in the Hundred Years’ War and brought Charles VII to be crowned at Reims; the English burned her as a heretic."}},
{id:"gutenberg",y:[1400,1468],ca:1,at:["strasbourg"],c:[8.27,50.00],pl:{en:"Mainz",zh:"美因茨"},n:{zh:"古腾堡",en:"Johannes Gutenberg"},r:{zh:"印刷术发明者",en:"Inventor of printing"},d:{zh:"在美因茨发明金属活字印刷机，印制了《古腾堡圣经》，此前曾在斯特拉斯堡试验。",en:"Developed printing with movable metal type in Mainz and printed the Gutenberg Bible, after early experiments in Strasbourg."}},
{id:"lorenzo-de-medici",y:[1449,1492],at:["florence"],n:{zh:"洛伦佐·德·美第奇",en:"Lorenzo de’ Medici"},r:{zh:"佛罗伦萨统治者",en:"Ruler of Florence"},d:{zh:"人称“伟大的洛伦佐”，佛罗伦萨的实际统治者，资助波提切利、米开朗琪罗等艺术家。",en:"Known as Lorenzo the Magnificent, the de facto ruler of Florence and patron of Botticelli, Michelangelo and others."}},
{id:"leonardo",y:[1452,1519],at:["florence","milan"],c:[10.92,43.79],pl:{en:"Vinci",zh:"芬奇镇"},n:{zh:"列奥纳多·达·芬奇",en:"Leonardo da Vinci"},r:{zh:"画家、发明家",en:"Painter and inventor"},d:{zh:"文艺复兴“全才”，作品有《蒙娜丽莎》与米兰的《最后的晚餐》，笔记涉及解剖、工程与飞行。",en:"Renaissance polymath who painted the Mona Lisa and the Last Supper in Milan and filled notebooks with anatomy, engineering and flying machines."}},
{id:"columbus",y:[1451,1506],at:["genoa","seville","santodomingo"],n:{zh:"克里斯托弗·哥伦布",en:"Christopher Columbus"},r:{zh:"航海家",en:"Navigator"},d:{zh:"生于热那亚，受西班牙双王资助于 1492 年横渡大西洋抵达加勒比海，开启欧洲对美洲的殖民。",en:"Genoese navigator who crossed the Atlantic for the Spanish monarchs in 1492 and reached the Caribbean, beginning European colonisation of the Americas."}},
{id:"henry-the-navigator",y:[1394,1460],at:["porto","lisbon"],n:{zh:"航海家恩里克",en:"Henry the Navigator"},r:{zh:"葡萄牙王子",en:"Portuguese prince"},d:{zh:"若昂一世之子，资助沿非洲西岸南下的航海探险，为葡萄牙海上帝国奠定基础。",en:"Son of John I who sponsored voyages down the west coast of Africa, laying the foundations of Portugal’s sea empire."}},
{id:"vasco-da-gama",y:[1469,1524],ca:1,at:["lisbon","calicut","goa"],n:{zh:"瓦斯科·达·伽马",en:"Vasco da Gama"},r:{zh:"航海家",en:"Navigator"},d:{zh:"1497 年从里斯本出发绕过好望角，1498 年抵达卡利卡特，开辟欧洲直达印度的航路；卒于印度。",en:"Sailed from Lisbon in 1497 around the Cape of Good Hope and reached Calicut in 1498, opening the sea route from Europe to India; he died in India."}},
{id:"machiavelli",y:[1469,1527],at:["florence"],n:{zh:"马基雅维利",en:"Niccolò Machiavelli"},r:{zh:"政治思想家",en:"Political thinker"},d:{zh:"佛罗伦萨共和国的外交官，美第奇家族复辟后写成《君主论》，开创了现实主义政治学。",en:"Diplomat of the Florentine Republic who, after the Medici returned, wrote The Prince and founded realist political thought."}},
{id:"copernicus",y:[1473,1543],at:["krakow","gdansk"],c:[18.60,53.01],pl:{en:"Toruń",zh:"托伦"},n:{zh:"尼古拉·哥白尼",en:"Nicolaus Copernicus"},r:{zh:"天文学家",en:"Astronomer"},d:{zh:"在克拉科夫求学，临终前出版《天体运行论》，提出日心说。",en:"Studied in Kraków and, as he was dying, published On the Revolutions of the Heavenly Spheres, setting the Sun at the centre."}},
{id:"michelangelo",y:[1475,1564],at:["florence","rome"],n:{zh:"米开朗琪罗",en:"Michelangelo"},r:{zh:"雕塑家、画家、建筑师",en:"Sculptor, painter and architect"},d:{zh:"创作了佛罗伦萨的《大卫》、西斯廷礼拜堂天顶画，并主持设计圣彼得大教堂穹顶。",en:"Carved the David in Florence, painted the Sistine Chapel ceiling and designed the dome of St Peter’s."}},
{id:"magellan",y:[1480,1521],ca:1,at:["seville","lisbon","manila"],n:{zh:"费迪南德·麦哲伦",en:"Ferdinand Magellan"},r:{zh:"航海家",en:"Navigator"},d:{zh:"葡萄牙航海家，为西班牙率船队从塞维利亚出发，穿越麦哲伦海峡横渡太平洋，在菲律宾战死；船队完成首次环球航行。",en:"Portuguese navigator who led a Spanish fleet from Seville through the strait that bears his name and across the Pacific; he was killed in the Philippines, but his ship completed the first circumnavigation."}},
{id:"luther",y:[1483,1546],at:[],c:[12.65,51.87],pl:{en:"Wittenberg",zh:"维滕贝格"},n:{zh:"马丁·路德",en:"Martin Luther"},r:{zh:"宗教改革家",en:"Reformer"},d:{zh:"维滕贝格大学教授，1517 年发表《九十五条论纲》，引发宗教改革，并将《圣经》译成德语。",en:"Professor at Wittenberg who published the Ninety-five Theses in 1517, setting off the Reformation, and translated the Bible into German."}},
{id:"raphael",y:[1483,1520],at:["rome","florence"],c:[12.64,43.73],pl:{en:"Urbino",zh:"乌尔比诺"},n:{zh:"拉斐尔",en:"Raphael"},r:{zh:"画家",en:"Painter"},d:{zh:"盛期文艺复兴画家，为梵蒂冈绘制《雅典学院》等壁画，三十七岁卒于罗马。",en:"High Renaissance painter of the School of Athens and other frescoes in the Vatican; he died in Rome aged thirty-seven."}},
{id:"durer",y:[1471,1528],at:["nuremberg","venice"],n:{zh:"阿尔布雷希特·丢勒",en:"Albrecht Dürer"},r:{zh:"画家、版画家",en:"Painter and printmaker"},d:{zh:"纽伦堡画家，两度游历意大利，把文艺复兴艺术带到北方，木刻与铜版画闻名欧洲。",en:"Nuremberg artist who twice travelled to Italy and brought the Renaissance north; his woodcuts and engravings were famous across Europe."}},
{id:"charles-v",y:[1500,1558],at:["brussels","toledo","bologna"],c:[3.72,51.05],pl:{en:"Ghent",zh:"根特"},n:{zh:"查理五世",en:"Charles V"},r:{zh:"神圣罗马皇帝、西班牙国王",en:"Holy Roman Emperor and King of Spain"},d:{zh:"生于根特，继承哈布斯堡、勃艮第与西班牙领地，统治“日不落”帝国，1556 年在布鲁塞尔退位。",en:"Born in Ghent, he inherited the Habsburg, Burgundian and Spanish lands, ruled an empire ‘on which the sun never set’ and abdicated in Brussels in 1556."}},
{id:"calvin",y:[1509,1564],at:["geneva","paris"],c:[3.00,49.58],pl:{en:"Noyon",zh:"努瓦永"},n:{zh:"约翰·加尔文",en:"John Calvin"},r:{zh:"宗教改革家",en:"Reformer"},d:{zh:"法国神学家，在日内瓦推行宗教改革，所著《基督教要义》影响了欧洲与北美的新教。",en:"French theologian who led the Reformation in Geneva; his Institutes shaped Protestantism in Europe and North America."}},
{id:"elizabeth-i",y:[1533,1603],at:["london"],n:{zh:"伊丽莎白一世",en:"Elizabeth I"},r:{zh:"英格兰女王",en:"Queen of England"},d:{zh:"都铎王朝末代君主，确立英格兰国教，1588 年击败西班牙无敌舰队，在位期间戏剧文学繁荣。",en:"Last Tudor monarch, who settled the Church of England, saw off the Spanish Armada in 1588 and reigned over a golden age of drama."}},
{id:"philip-ii",y:[1527,1598],at:["madrid","toledo","lisbon"],c:[-4.72,41.65],pl:{en:"Valladolid",zh:"巴利亚多利德"},n:{zh:"腓力二世",en:"Philip II"},r:{zh:"西班牙国王",en:"King of Spain"},d:{zh:"定都马德里，1580 年兼任葡萄牙国王，统治横跨美洲与亚洲的帝国，菲律宾即以他命名。",en:"Settled the court in Madrid, became King of Portugal in 1580 and ruled an empire spanning the Americas and Asia; the Philippines are named after him."}},
{id:"cervantes",y:[1547,1616],at:["madrid","seville"],c:[-3.36,40.48],pl:{en:"Alcalá de Henares",zh:"阿尔卡拉"},n:{zh:"塞万提斯",en:"Miguel de Cervantes"},r:{zh:"作家",en:"Writer"},d:{zh:"曾参加勒班陀海战并被阿尔及尔海盗俘虏五年，晚年写成《堂吉诃德》，被视为第一部现代小说。",en:"Fought at Lepanto and spent five years as a captive in Algiers; late in life he wrote Don Quixote, often called the first modern novel."}},
{id:"shakespeare",y:[1564,1616],at:["london"],c:[-1.71,52.19],pl:{en:"Stratford-upon-Avon",zh:"斯特拉特福"},n:{zh:"威廉·莎士比亚",en:"William Shakespeare"},r:{zh:"剧作家、诗人",en:"Playwright and poet"},d:{zh:"在伦敦环球剧场写作与演出，留下《哈姆雷特》《李尔王》等近四十部剧作。",en:"Wrote and acted for the Globe in London, leaving nearly forty plays including Hamlet and King Lear."}},
{id:"galileo",y:[1564,1642],at:["florence","rome"],c:[10.40,43.72],pl:{en:"Pisa",zh:"比萨"},n:{zh:"伽利略",en:"Galileo Galilei"},r:{zh:"科学家",en:"Scientist"},d:{zh:"用望远镜发现木星卫星与金星相位，支持日心说，1633 年在罗马受宗教裁判所审判，余生软禁于佛罗伦萨附近。",en:"Used the telescope to find Jupiter’s moons and the phases of Venus in support of Copernicus; tried by the Inquisition in Rome in 1633, he spent his last years under house arrest near Florence."}},
{id:"rubens",y:[1577,1640],at:["antwerp"],n:{zh:"彼得·保罗·鲁本斯",en:"Peter Paul Rubens"},r:{zh:"画家",en:"Painter"},d:{zh:"安特卫普的巴洛克画家与外交官，工作室为欧洲各国宫廷绘制大型作品。",en:"Baroque painter and diplomat of Antwerp whose workshop produced great canvases for the courts of Europe."}},
{id:"descartes",y:[1596,1650],at:["amsterdam","stockholm","paris"],c:[0.70,46.97],pl:{en:"La Haye en Touraine",zh:"拉艾"},n:{zh:"勒内·笛卡尔",en:"René Descartes"},r:{zh:"哲学家、数学家",en:"Philosopher and mathematician"},d:{zh:"“我思故我在”，长期旅居荷兰，创立解析几何，应克里斯蒂娜女王之邀赴斯德哥尔摩，次年病逝。",en:"‘I think, therefore I am.’ He lived for years in the Dutch Republic, created analytic geometry and died in Stockholm after joining Queen Christina’s court."}},
{id:"rembrandt",y:[1606,1669],at:["amsterdam"],c:[4.49,52.16],pl:{en:"Leiden",zh:"莱顿"},n:{zh:"伦勃朗",en:"Rembrandt"},r:{zh:"画家",en:"Painter"},d:{zh:"荷兰黄金时代最伟大的画家，代表作《夜巡》，晚年在阿姆斯特丹破产。",en:"The greatest painter of the Dutch Golden Age, known for The Night Watch; he went bankrupt in Amsterdam late in life."}},
{id:"spinoza",y:[1632,1677],at:["amsterdam"],n:{zh:"巴鲁赫·斯宾诺莎",en:"Baruch Spinoza"},r:{zh:"哲学家",en:"Philosopher"},d:{zh:"阿姆斯特丹的犹太裔哲学家，被犹太社群开除教籍，以磨镜片为生，著有《伦理学》。",en:"Philosopher from Amsterdam’s Jewish community, which expelled him; he ground lenses for a living and wrote the Ethics."}},
{id:"louis-xiv",y:[1638,1715],at:["paris"],c:[2.09,48.90],pl:{en:"Saint-Germain-en-Laye",zh:"圣日耳曼昂莱"},n:{zh:"路易十四",en:"Louis XIV"},r:{zh:"法国国王",en:"King of France"},d:{zh:"“太阳王”，在位七十二年，修建凡尔赛宫，是欧洲绝对君主制的典型。",en:"The ‘Sun King’, who reigned for seventy-two years, built Versailles and became the model of absolute monarchy."}},
{id:"newton",y:[1643,1727],at:["london"],c:[0.12,52.21],pl:{en:"Cambridge",zh:"剑桥"},n:{zh:"艾萨克·牛顿",en:"Isaac Newton"},r:{zh:"科学家",en:"Scientist"},d:{zh:"剑桥学者，《自然哲学的数学原理》提出万有引力与运动定律，后任伦敦皇家铸币厂厂长。",en:"Cambridge scholar whose Principia set out the laws of motion and universal gravitation; he later ran the Royal Mint in London."}},
{id:"peter-the-great",y:[1672,1725],at:["moscow","stpete"],n:{zh:"彼得大帝",en:"Peter the Great"},r:{zh:"俄国沙皇",en:"Tsar of Russia"},d:{zh:"亲赴西欧学习，推行西化改革，击败瑞典取得波罗的海出海口，建圣彼得堡并迁都。",en:"Toured western Europe, forced through westernising reforms, defeated Sweden for access to the Baltic and built St Petersburg as his new capital."}},
{id:"bach",y:[1685,1750],at:[],c:[12.37,51.34],pl:{en:"Leipzig",zh:"莱比锡"},n:{zh:"约翰·塞巴斯蒂安·巴赫",en:"Johann Sebastian Bach"},r:{zh:"作曲家",en:"Composer"},d:{zh:"巴洛克音乐的集大成者，晚年任莱比锡圣托马斯教堂乐长，作品有《马太受难曲》和《平均律钢琴曲集》。",en:"The culmination of Baroque music, cantor of St Thomas’s in Leipzig in his last decades; his works include the St Matthew Passion and the Well-Tempered Clavier."}},
{id:"voltaire",y:[1694,1778],at:["paris","geneva"],n:{zh:"伏尔泰",en:"Voltaire"},r:{zh:"启蒙思想家",en:"Enlightenment writer"},d:{zh:"以讽刺抨击教会与专制，倡导宗教宽容，晚年住在日内瓦附近的费内。",en:"Satirist who attacked the Church and arbitrary power and championed religious tolerance; he spent his later years at Ferney near Geneva."}},
{id:"rousseau",y:[1712,1778],at:["geneva","paris"],n:{zh:"让-雅克·卢梭",en:"Jean-Jacques Rousseau"},r:{zh:"思想家",en:"Philosopher"},d:{zh:"生于日内瓦，《社会契约论》提出人民主权学说，深刻影响了法国大革命。",en:"Born in Geneva, he wrote The Social Contract on popular sovereignty, a major influence on the French Revolution."}},
{id:"kant",y:[1724,1804],at:["konigsberg"],n:{zh:"伊曼努尔·康德",en:"Immanuel Kant"},r:{zh:"哲学家",en:"Philosopher"},d:{zh:"终生生活在柯尼斯堡，著有《纯粹理性批判》，是启蒙运动最重要的哲学家之一。",en:"Spent his whole life in Königsberg and wrote the Critique of Pure Reason, making him one of the central philosophers of the Enlightenment."}},
{id:"catherine-the-great",y:[1729,1796],at:["stpete","odesa","sevastopol"],c:[14.55,53.43],pl:{en:"Stettin",zh:"什切青"},n:{zh:"叶卡捷琳娜二世",en:"Catherine the Great"},r:{zh:"俄国女皇",en:"Empress of Russia"},d:{zh:"德意志公主出身，推翻丈夫登基，兼并克里米亚、参与瓜分波兰，下令建立敖德萨。",en:"A German princess who overthrew her husband to take the throne, annexed Crimea, joined the partitions of Poland and ordered Odesa founded."}},
{id:"goethe",y:[1749,1832],at:[],c:[8.68,50.11],pl:{en:"Frankfurt and Weimar",zh:"法兰克福、魏玛"},n:{zh:"歌德",en:"Johann Wolfgang von Goethe"},r:{zh:"作家",en:"Writer"},d:{zh:"生于法兰克福，在魏玛宫廷任职数十年，代表作《少年维特之烦恼》与《浮士德》。",en:"Born in Frankfurt, he served the court of Weimar for decades; his works include The Sorrows of Young Werther and Faust."}},
{id:"mozart",y:[1756,1791],at:["salzburg","vienna","prague"],n:{zh:"沃尔夫冈·阿玛多伊斯·莫扎特",en:"Wolfgang Amadeus Mozart"},r:{zh:"作曲家",en:"Composer"},d:{zh:"萨尔茨堡出生的神童，后定居维也纳，创作歌剧《费加罗的婚礼》《唐璜》（首演于布拉格）等，三十五岁去世。",en:"Child prodigy from Salzburg who settled in Vienna and wrote operas including The Marriage of Figaro and Don Giovanni, first staged in Prague; he died at thirty-five."}},
{id:"napoleon",y:[1769,1821],at:["paris","moscow"],c:[8.74,41.92],pl:{en:"Ajaccio",zh:"阿雅克肖"},n:{zh:"拿破仑·波拿巴",en:"Napoleon Bonaparte"},r:{zh:"法国皇帝",en:"Emperor of the French"},d:{zh:"生于科西嘉，大革命中崛起，1804 年称帝，颁布《拿破仑法典》，征服欧洲大部，滑铁卢战败后被流放圣赫勒拿岛。",en:"Corsican who rose in the Revolution, crowned himself emperor in 1804, issued the Napoleonic Code and conquered much of Europe; after Waterloo he was exiled to St Helena."}},
{id:"beethoven",y:[1770,1827],at:["vienna"],c:[7.10,50.73],pl:{en:"Bonn",zh:"波恩"},n:{zh:"路德维希·凡·贝多芬",en:"Ludwig van Beethoven"},r:{zh:"作曲家",en:"Composer"},d:{zh:"生于波恩，在维也纳度过创作生涯，耳聋后仍写出《第九交响曲》，连接古典与浪漫主义。",en:"Born in Bonn, he worked in Vienna and, though deaf, composed the Ninth Symphony, bridging the Classical and Romantic eras."}},
{id:"chopin",y:[1810,1849],at:["warsaw","paris"],n:{zh:"弗雷德里克·肖邦",en:"Frédéric Chopin"},r:{zh:"作曲家、钢琴家",en:"Composer and pianist"},d:{zh:"在华沙长大，1830 年起旅居巴黎，钢琴作品融入波兰民族音乐，心脏被送回华沙安葬。",en:"Raised in Warsaw, he lived in Paris from 1830; his piano music draws on Polish dances, and his heart was returned to Warsaw."}},
{id:"garibaldi",y:[1807,1882],at:["palermo","naples","rome"],c:[7.27,43.70],pl:{en:"Nice",zh:"尼斯"},n:{zh:"朱塞佩·加里波第",en:"Giuseppe Garibaldi"},r:{zh:"意大利统一运动领袖",en:"Leader of Italian unification"},d:{zh:"率“千人军”远征西西里与那不勒斯，推翻两西西里王国，促成意大利统一。",en:"Led the Thousand to conquer Sicily and Naples, toppling the Kingdom of the Two Sicilies and helping to unite Italy."}},
{id:"darwin",y:[1809,1882],at:["london"],c:[-2.75,52.71],pl:{en:"Shrewsbury",zh:"什鲁斯伯里"},n:{zh:"查尔斯·达尔文",en:"Charles Darwin"},r:{zh:"博物学家",en:"Naturalist"},d:{zh:"随“小猎犬号”环球考察，1859 年出版《物种起源》，提出自然选择学说。",en:"Sailed round the world on the Beagle and in 1859 published On the Origin of Species, setting out evolution by natural selection."}},
{id:"queen-victoria",y:[1819,1901],at:["london"],n:{zh:"维多利亚女王",en:"Queen Victoria"},r:{zh:"英国女王",en:"Queen of the United Kingdom"},d:{zh:"在位六十三年，英国工业与殖民帝国达到顶峰，1876 年加冕印度女皇。",en:"Reigned for sixty-three years over the height of Britain’s industrial and imperial power, and became Empress of India in 1876."}},
{id:"victor-hugo",y:[1802,1885],at:["paris"],c:[6.02,47.24],pl:{en:"Besançon",zh:"贝桑松"},n:{zh:"维克多·雨果",en:"Victor Hugo"},r:{zh:"作家",en:"Writer"},d:{zh:"法国浪漫主义文学领袖，著有《巴黎圣母院》《悲惨世界》，因反对拿破仑三世流亡近二十年。",en:"Leader of French Romanticism, author of Notre-Dame de Paris and Les Misérables; he spent nearly twenty years in exile for opposing Napoleon III."}},
{id:"bismarck",y:[1815,1898],at:["berlin"],n:{zh:"奥托·冯·俾斯麦",en:"Otto von Bismarck"},r:{zh:"德意志帝国首相",en:"Chancellor of Germany"},d:{zh:"普鲁士首相，通过三次战争实现德意志统一，1871 年任德意志帝国首相。",en:"Prussian minister-president who unified Germany through three wars and became the first chancellor of the German Empire in 1871."}},
{id:"marx",y:[1818,1883],at:["trier","london","paris"],n:{zh:"卡尔·马克思",en:"Karl Marx"},r:{zh:"思想家",en:"Philosopher and economist"},d:{zh:"生于特里尔，与恩格斯合著《共产党宣言》，流亡伦敦期间写成《资本论》。",en:"Born in Trier, he wrote The Communist Manifesto with Engels and, in exile in London, Capital."}},
{id:"dostoevsky",y:[1821,1881],at:["moscow","stpete"],n:{zh:"陀思妥耶夫斯基",en:"Fyodor Dostoevsky"},r:{zh:"作家",en:"Writer"},d:{zh:"生于莫斯科，曾被流放西伯利亚，在圣彼得堡写成《罪与罚》《卡拉马佐夫兄弟》。",en:"Born in Moscow and exiled to Siberia, he wrote Crime and Punishment and The Brothers Karamazov in St Petersburg."}},
{id:"tolstoy",y:[1828,1910],at:["moscow"],c:[37.53,54.08],pl:{en:"Yasnaya Polyana",zh:"亚斯纳亚·波利亚纳"},n:{zh:"列夫·托尔斯泰",en:"Leo Tolstoy"},r:{zh:"作家",en:"Writer"},d:{zh:"俄国作家，曾参加克里米亚战争中的塞瓦斯托波尔保卫战，著有《战争与和平》《安娜·卡列尼娜》。",en:"Russian novelist who fought at Sevastopol in the Crimean War and wrote War and Peace and Anna Karenina."}},
{id:"tchaikovsky",y:[1840,1893],at:["stpete","moscow"],c:[52.30,58.06],pl:{en:"Votkinsk",zh:"沃特金斯克"},n:{zh:"柴可夫斯基",en:"Pyotr Ilyich Tchaikovsky"},r:{zh:"作曲家",en:"Composer"},d:{zh:"俄国作曲家，作品有芭蕾舞剧《天鹅湖》《胡桃夹子》及《第六交响曲》。",en:"Russian composer of the ballets Swan Lake and The Nutcracker and of the Sixth Symphony."}},
{id:"marie-curie",y:[1867,1934],at:["warsaw","paris"],n:{zh:"玛丽·居里",en:"Marie Curie"},r:{zh:"物理学家、化学家",en:"Physicist and chemist"},d:{zh:"生于华沙，在巴黎研究放射性，发现钋和镭，是第一位两次获得诺贝尔奖的人。",en:"Born in Warsaw, she studied radioactivity in Paris, discovered polonium and radium and was the first person to win two Nobel Prizes."}},
{id:"freud",y:[1856,1939],at:["vienna","london"],c:[18.15,49.59],pl:{en:"Příbor",zh:"普日博尔"},n:{zh:"西格蒙德·弗洛伊德",en:"Sigmund Freud"},r:{zh:"精神分析学创始人",en:"Founder of psychoanalysis"},d:{zh:"在维也纳行医数十年，创立精神分析学，1938 年为躲避纳粹流亡伦敦。",en:"Practised in Vienna for decades and founded psychoanalysis; he fled the Nazis to London in 1938."}},
{id:"lenin",y:[1870,1924],at:["kazan","stpete","moscow"],c:[48.40,54.32],pl:{en:"Simbirsk",zh:"辛比尔斯克"},n:{zh:"列宁",en:"Vladimir Lenin"},r:{zh:"布尔什维克领袖",en:"Bolshevik leader"},d:{zh:"在喀山求学时投身革命，领导 1917 年十月革命，建立苏维埃政权并迁都莫斯科。",en:"Turned to revolution as a student in Kazan, led the October Revolution of 1917 and founded the Soviet state with its capital in Moscow."}},
{id:"churchill",y:[1874,1965],at:["london"],c:[-1.36,51.84],pl:{en:"Blenheim Palace",zh:"布伦海姆宫"},n:{zh:"温斯顿·丘吉尔",en:"Winston Churchill"},r:{zh:"英国首相",en:"British prime minister"},d:{zh:"第二次世界大战期间领导英国抵抗纳粹德国，1953 年获诺贝尔文学奖。",en:"Led Britain against Nazi Germany in the Second World War and won the Nobel Prize in Literature in 1953."}},
{id:"stalin",y:[1878,1953],at:["tbilisi","moscow"],c:[44.11,41.98],pl:{en:"Gori",zh:"哥里"},n:{zh:"约瑟夫·斯大林",en:"Joseph Stalin"},r:{zh:"苏联领导人",en:"Soviet leader"},d:{zh:"生于格鲁吉亚，列宁死后掌握苏联最高权力，推行集体化与工业化，发动大清洗，领导苏联赢得卫国战争。",en:"Georgian who took control of the Soviet Union after Lenin, forced collectivisation and industrialisation, ran the Great Purge and led the country to victory in the Second World War."}},
{id:"einstein",y:[1879,1955],at:["berlin","prague"],c:[9.99,48.40],pl:{en:"Ulm",zh:"乌尔姆"},n:{zh:"阿尔伯特·爱因斯坦",en:"Albert Einstein"},r:{zh:"物理学家",en:"Physicist"},d:{zh:"提出狭义与广义相对论，曾在布拉格与柏林任教，1933 年移居美国。",en:"Developed the special and general theories of relativity, taught in Prague and Berlin, and moved to the United States in 1933."}},
{id:"kafka",y:[1883,1924],at:["prague"],n:{zh:"弗朗茨·卡夫卡",en:"Franz Kafka"},r:{zh:"作家",en:"Writer"},d:{zh:"布拉格的德语犹太作家，生前在保险公司任职，《变形记》《审判》在他死后才广为人知。",en:"German-speaking Jewish writer of Prague who worked for an insurance office; The Metamorphosis and The Trial became famous only after his death."}},
{id:"de-gaulle",y:[1890,1970],at:["paris","london"],c:[3.06,50.63],pl:{en:"Lille",zh:"里尔"},n:{zh:"夏尔·戴高乐",en:"Charles de Gaulle"},r:{zh:"法国总统",en:"President of France"},d:{zh:"1940 年在伦敦号召法国人继续抵抗，领导“自由法国”，1958 年创建第五共和国。",en:"Called on the French to fight on from London in 1940, led Free France and founded the Fifth Republic in 1958."}},
// ---- China ----
{id:"confucius",y:[-551,-479],at:["qufu"],n:{zh:"孔子",en:"Confucius"},r:{zh:"思想家、教育家",en:"Philosopher and teacher"},d:{zh:"春秋时鲁国人，周游列国宣扬仁政与礼制，弟子编成的《论语》成为两千多年中国思想的核心。",en:"Thinker from the state of Lu who travelled the states urging rule by virtue and ritual; the Analects compiled by his disciples became the core of Chinese thought for two thousand years."}},
{id:"qin-shi-huang",y:[-259,-210],at:["xian"],c:[114.49,36.61],pl:{en:"Handan",zh:"邯郸"},n:{zh:"秦始皇",en:"Qin Shi Huang"},r:{zh:"中国第一位皇帝",en:"First Emperor of China"},d:{zh:"生于赵国邯郸，公元前 221 年统一六国，建立郡县制，统一文字、度量衡与货币，陵墓旁埋有兵马俑。",en:"Born in Handan, he unified China in 221 BC, created a system of commanderies and standardised writing, weights and coinage; the Terracotta Army guards his tomb."}},
{id:"liu-bang",y:[-256,-195],at:["xian"],c:[116.93,34.73],pl:{en:"Pei",zh:"沛县"},n:{zh:"刘邦（汉高祖）",en:"Liu Bang (Emperor Gaozu of Han)"},r:{zh:"汉朝开国皇帝",en:"Founder of the Han dynasty"},d:{zh:"出身平民，秦末起兵，击败项羽后建立汉朝，定都长安。",en:"A commoner who rose in revolt against Qin, defeated Xiang Yu and founded the Han dynasty with its capital at Chang’an."}},
{id:"han-wudi",y:[-156,-87],at:["xian","dunhuang"],n:{zh:"汉武帝",en:"Emperor Wu of Han"},r:{zh:"汉朝皇帝",en:"Han emperor"},d:{zh:"在位五十四年，北击匈奴，设河西四郡，派张骞出使西域，独尊儒术。",en:"Reigned for fifty-four years, fought the Xiongnu, set up the Hexi commanderies including Dunhuang, sent Zhang Qian to Central Asia and made Confucianism the state teaching."}},
{id:"zhang-qian",y:[-164,-113],ca:1,at:["xian","dunhuang","kashgar"],n:{zh:"张骞",en:"Zhang Qian"},r:{zh:"外交家、探险家",en:"Envoy and explorer"},d:{zh:"奉汉武帝之命出使西域，两度被匈奴扣留，抵达大宛、大夏等地，被视为丝绸之路的开拓者。",en:"Sent west by Emperor Wu, twice held captive by the Xiongnu, he reached Ferghana and Bactria and is regarded as the pioneer of the Silk Road."}},
{id:"sima-qian",y:[-145,-86],ca:1,at:["xian"],n:{zh:"司马迁",en:"Sima Qian"},r:{zh:"史学家",en:"Historian"},d:{zh:"西汉太史令，受宫刑后发愤完成《史记》，开创纪传体史书。",en:"Grand Historian of the Western Han who, after being sentenced to castration, completed the Records of the Grand Historian, the model for Chinese official histories."}},
{id:"cao-cao",y:[155,220],at:["luoyang"],c:[115.78,33.85],pl:{en:"Bozhou",zh:"亳州"},n:{zh:"曹操",en:"Cao Cao"},r:{zh:"东汉末年权臣、诗人",en:"Warlord and poet"},d:{zh:"挟天子以令诸侯，统一北方，为曹魏奠定基础，也是建安文学的代表诗人，卒于洛阳。",en:"Controlled the last Han emperor, united northern China and laid the foundations of Cao Wei; also a leading poet, he died in Luoyang."}},
{id:"liu-bei",y:[161,223],at:["chengdu"],c:[115.97,39.48],pl:{en:"Zhuozhou",zh:"涿州"},n:{zh:"刘备",en:"Liu Bei"},r:{zh:"蜀汉开国皇帝",en:"Founder of Shu Han"},d:{zh:"汉室宗亲，三顾茅庐请出诸葛亮，入蜀后于 221 年在成都称帝。",en:"A distant member of the Han royal house who recruited Zhuge Liang, took Shu and proclaimed himself emperor at Chengdu in 221."}},
{id:"zhuge-liang",y:[181,234],at:["chengdu"],n:{zh:"诸葛亮",en:"Zhuge Liang"},r:{zh:"蜀汉丞相",en:"Chancellor of Shu Han"},d:{zh:"辅佐刘备父子，六出祁山北伐曹魏，病逝于五丈原，被后世视为忠臣与智者的典范。",en:"Served Liu Bei and his son as chancellor and led repeated northern campaigns against Wei; he died at Wuzhang Plains and became China’s model of loyalty and wisdom."}},
{id:"wang-xizhi",y:[303,361],at:["nanjing"],c:[120.58,30.00],pl:{en:"Shaoxing",zh:"绍兴"},n:{zh:"王羲之",en:"Wang Xizhi"},r:{zh:"书法家",en:"Calligrapher"},d:{zh:"东晋书法家，被尊为“书圣”，《兰亭集序》写于会稽（今绍兴）。",en:"Calligrapher of the Eastern Jin known as the ‘Sage of Calligraphy’; he wrote the Lanting Preface at Kuaiji, today’s Shaoxing."}},
{id:"tang-taizong",y:[598,649],at:["xian"],n:{zh:"唐太宗",en:"Emperor Taizong of Tang"},r:{zh:"唐朝皇帝",en:"Tang emperor"},d:{zh:"李世民，玄武门之变后即位，开创“贞观之治”，被西北诸族尊为“天可汗”。",en:"Li Shimin, who took the throne after the Xuanwu Gate incident, presided over the Zhenguan era and was hailed by the steppe peoples as ‘Heavenly Khan’."}},
{id:"xuanzang",y:[602,664],at:["xian","dunhuang","taxila","patna"],c:[112.77,34.62],pl:{en:"Yanshi, near Luoyang",zh:"洛阳偃师"},n:{zh:"玄奘",en:"Xuanzang"},r:{zh:"高僧、翻译家",en:"Buddhist monk and translator"},d:{zh:"从长安西行求法，在那烂陀寺学习多年，携经卷返回长安翻译，口述成《大唐西域记》。",en:"Left Chang’an for India, studied for years at Nalanda, returned with hundreds of scriptures to translate, and dictated the Great Tang Records on the Western Regions."}},
{id:"wu-zetian",y:[624,705],at:["luoyang","xian"],n:{zh:"武则天",en:"Wu Zetian"},r:{zh:"中国唯一的女皇帝",en:"China’s only empress regnant"},d:{zh:"唐高宗的皇后，690 年称帝建立武周，以洛阳为“神都”，晚年被迫退位。",en:"Empress of Gaozong of Tang who in 690 declared her own Zhou dynasty, ruled from Luoyang as the ‘divine capital’ and was forced to abdicate at the end of her life."}},
{id:"li-bai",y:[701,762],at:["xian"],c:[74.99,42.84],pl:{en:"Suyab (by tradition)",zh:"碎叶（一说）"},n:{zh:"李白",en:"Li Bai"},r:{zh:"诗人",en:"Poet"},d:{zh:"盛唐浪漫主义诗人，号“诗仙”，曾在长安供奉翰林，一生漫游各地。",en:"Romantic poet of the high Tang, the ‘Immortal of Poetry’, who served briefly at court in Chang’an and spent his life wandering."}},
{id:"du-fu",y:[712,770],at:["chengdu","xian","luoyang"],n:{zh:"杜甫",en:"Du Fu"},r:{zh:"诗人",en:"Poet"},d:{zh:"号“诗圣”，经历安史之乱，诗作记录时代苦难，在成都草堂居住数年。",en:"The ‘Sage of Poetry’, whose verse records the suffering of the An Lushan rebellion; he lived for several years in a thatched cottage in Chengdu."}},
{id:"song-taizu",y:[927,976],at:["kaifeng","luoyang"],n:{zh:"赵匡胤（宋太祖）",en:"Zhao Kuangyin (Emperor Taizu of Song)"},r:{zh:"宋朝开国皇帝",en:"Founder of the Song dynasty"},d:{zh:"后周禁军统帅，960 年陈桥兵变黄袍加身，建立宋朝，定都开封，以“杯酒释兵权”削弱武将。",en:"Commander of the Later Zhou guards who was proclaimed emperor by his troops in 960, founded the Song with its capital at Kaifeng and curbed the power of the generals."}},
{id:"su-shi",y:[1037,1101],at:["hangzhou","kaifeng"],c:[103.83,30.05],pl:{en:"Meishan",zh:"眉山"},n:{zh:"苏轼",en:"Su Shi"},r:{zh:"文学家、书画家",en:"Writer, painter and calligrapher"},d:{zh:"北宋文豪，诗词书画皆精，两任杭州地方官，修筑西湖苏堤，屡遭贬谪。",en:"Song writer, painter and calligrapher who twice governed Hangzhou, built the Su Causeway on West Lake and was repeatedly sent into exile."}},
{id:"yue-fei",y:[1103,1142],at:["hangzhou","kaifeng"],c:[114.38,35.90],pl:{en:"Tangyin",zh:"汤阴"},n:{zh:"岳飞",en:"Yue Fei"},r:{zh:"南宋将领",en:"Southern Song general"},d:{zh:"抗金名将，北伐屡胜，却被召回并以“莫须有”罪名在临安被害，后世奉为民族英雄。",en:"General who won repeated victories against the Jin but was recalled and put to death in Lin’an (Hangzhou) on false charges; he is honoured as a national hero."}},
{id:"genghis-khan",y:[1162,1227],ca:1,at:["karakorum","bukhara","beijing"],n:{zh:"成吉思汗",en:"Genghis Khan"},r:{zh:"蒙古帝国创建者",en:"Founder of the Mongol Empire"},d:{zh:"铁木真于 1206 年统一蒙古各部，被尊为成吉思汗，此后攻金、灭西夏、西征花剌子模，奠定了蒙古帝国。",en:"Temüjin united the Mongol tribes in 1206 as Genghis Khan and went on to attack the Jin, destroy the Western Xia and conquer Khwarazm, founding the Mongol Empire."}},
{id:"kublai-khan",y:[1215,1294],at:["beijing","karakorum","hangzhou"],n:{zh:"忽必烈",en:"Kublai Khan"},r:{zh:"元朝开国皇帝",en:"Founder of the Yuan dynasty"},d:{zh:"成吉思汗之孙，1271 年建立元朝，定都大都（今北京），1279 年灭南宋统一中国。",en:"Grandson of Genghis Khan who proclaimed the Yuan dynasty in 1271, built his capital Dadu (Beijing) and conquered the Southern Song in 1279."}},
{id:"hongwu",y:[1328,1398],at:["nanjing"],c:[117.37,32.94],pl:{en:"Fengyang",zh:"凤阳"},n:{zh:"朱元璋（明太祖）",en:"Zhu Yuanzhang (Hongwu Emperor)"},r:{zh:"明朝开国皇帝",en:"Founder of the Ming dynasty"},d:{zh:"出身贫农，曾为僧人，元末起兵，1368 年在南京称帝建立明朝，将元朝逐出中原。",en:"A poor peasant and former monk who rose in the rebellions against the Yuan and founded the Ming at Nanjing in 1368, driving the Mongols from China."}},
{id:"yongle",y:[1360,1424],at:["beijing","nanjing"],n:{zh:"朱棣（明成祖）",en:"Zhu Di (Yongle Emperor)"},r:{zh:"明朝皇帝",en:"Ming emperor"},d:{zh:"靖难之役夺取皇位，迁都北京并营建紫禁城，派郑和下西洋，编纂《永乐大典》。",en:"Seized the throne in civil war, moved the capital to Beijing and built the Forbidden City, sent Zheng He’s fleets abroad and commissioned the Yongle Encyclopedia."}},
{id:"zheng-he",y:[1371,1433],at:["nanjing","malacca","calicut","mogadishu"],c:[102.62,24.68],pl:{en:"Kunyang, Yunnan",zh:"云南昆阳"},n:{zh:"郑和",en:"Zheng He"},r:{zh:"航海家",en:"Admiral and explorer"},d:{zh:"云南回族人，1405 年至 1433 年七次率船队从南京出发下西洋，远达东非。",en:"Muslim from Yunnan who between 1405 and 1433 led seven great fleets from Nanjing across the Indian Ocean as far as East Africa."}},
{id:"matteo-ricci",y:[1552,1610],at:["macau","beijing"],c:[13.45,43.30],pl:{en:"Macerata",zh:"马切拉塔"},n:{zh:"利玛窦",en:"Matteo Ricci"},r:{zh:"耶稣会传教士",en:"Jesuit missionary"},d:{zh:"意大利耶稣会士，经澳门进入中国，在北京传教，与徐光启合译《几何原本》，绘制《坤舆万国全图》。",en:"Italian Jesuit who entered China through Macau, worked in Beijing, translated Euclid with Xu Guangqi and drew a great world map for Chinese readers."}},
{id:"kangxi",y:[1654,1722],at:["beijing"],n:{zh:"康熙帝",en:"Kangxi Emperor"},r:{zh:"清朝皇帝",en:"Qing emperor"},d:{zh:"在位六十一年，平定三藩、收复台湾，与俄国签订《尼布楚条约》。",en:"Reigned for sixty-one years, crushed the Three Feudatories, took Taiwan and signed the Treaty of Nerchinsk with Russia."}},
{id:"qianlong",y:[1711,1799],at:["beijing","kashgar"],n:{zh:"乾隆帝",en:"Qianlong Emperor"},r:{zh:"清朝皇帝",en:"Qing emperor"},d:{zh:"清朝疆域在其治下达到最大，平定准噶尔与回部，1793 年接见马戛尔尼使团。",en:"Under him the Qing reached its greatest extent with the conquest of Dzungaria and the Tarim Basin; he received the Macartney embassy in 1793."}},
{id:"lin-zexu",y:[1785,1850],at:["guangzhou"],c:[119.30,26.08],pl:{en:"Fuzhou",zh:"福州"},n:{zh:"林则徐",en:"Lin Zexu"},r:{zh:"清朝官员",en:"Qing official"},d:{zh:"1839 年在广州主持虎门销烟，此事成为第一次鸦片战争的导火索。",en:"Destroyed the British opium stocks at Humen near Guangzhou in 1839, an act that led to the First Opium War."}},
{id:"cixi",y:[1835,1908],at:["beijing"],n:{zh:"慈禧太后",en:"Empress Dowager Cixi"},r:{zh:"清朝实际统治者",en:"De facto ruler of Qing China"},d:{zh:"咸丰帝的妃子，同治、光绪两朝垂帘听政近半个世纪，1898 年镇压戊戌变法。",en:"Consort of the Xianfeng Emperor who controlled the Qing government for almost half a century and crushed the reform movement of 1898."}},
{id:"sun-yat-sen",y:[1866,1925],at:["guangzhou","nanjing","hongkong"],c:[113.53,22.43],pl:{en:"Cuiheng, Zhongshan",zh:"中山翠亨村"},n:{zh:"孙中山",en:"Sun Yat-sen"},r:{zh:"中华民国创建者",en:"Founder of the Republic of China"},d:{zh:"曾在香港学医，领导推翻清朝的革命，1912 年在南京就任临时大总统，提出三民主义。",en:"Studied medicine in Hong Kong, led the revolution against the Qing, became provisional president in Nanjing in 1912 and set out the Three Principles of the People."}},
// ---- Japan & Korea ----
{id:"prince-shotoku",y:[574,622],at:["nara"],n:{zh:"圣德太子",en:"Prince Shōtoku"},r:{zh:"日本摄政",en:"Regent of Japan"},d:{zh:"推古天皇的摄政，制定《十七条宪法》，派遣遣隋使，创建法隆寺。",en:"Regent for Empress Suiko who issued the Seventeen-Article Constitution, sent envoys to Sui China and founded Hōryū-ji."}},
{id:"wang-geon",y:[877,943],at:["kaesong"],n:{zh:"王建（高丽太祖）",en:"Wang Geon (Taejo of Goryeo)"},r:{zh:"高丽开国君主",en:"Founder of Goryeo"},d:{zh:"918 年建立高丽，定都开京，935 年接受新罗投降，次年统一后三国。",en:"Founded Goryeo in 918 with its capital at Gaegyeong, accepted Silla’s surrender in 935 and reunited the peninsula the following year."}},
{id:"murasaki-shikibu",y:[973,1014],ca:1,at:["kyoto"],n:{zh:"紫式部",en:"Murasaki Shikibu"},r:{zh:"作家",en:"Writer"},d:{zh:"平安时代宫廷女官，所著《源氏物语》被视为世界上最早的长篇小说之一。",en:"Lady-in-waiting at the Heian court whose Tale of Genji is counted among the world’s first novels."}},
{id:"minamoto-no-yoritomo",y:[1147,1199],at:["kamakura","kyoto"],n:{zh:"源赖朝",en:"Minamoto no Yoritomo"},r:{zh:"镰仓幕府将军",en:"First Kamakura shogun"},d:{zh:"在源平合战中击败平氏，1192 年受封征夷大将军，开创日本延续近七百年的幕府政治。",en:"Defeated the Taira in the Genpei War and in 1192 became shogun, beginning nearly seven centuries of warrior government in Japan."}},
{id:"sejong",y:[1397,1450],at:["seoul"],n:{zh:"世宗大王",en:"Sejong the Great"},r:{zh:"朝鲜国王",en:"King of Joseon"},d:{zh:"朝鲜王朝第四代国王，主持创制韩文字母“训民正音”，推动天文与农业研究。",en:"Fourth king of Joseon who created the Korean alphabet, Hangul, and promoted astronomy and agricultural science."}},
{id:"oda-nobunaga",y:[1534,1582],at:["kyoto"],c:[136.91,35.18],pl:{en:"Owari (Nagoya)",zh:"尾张（名古屋）"},n:{zh:"织田信长",en:"Oda Nobunaga"},r:{zh:"战国大名",en:"Warlord"},d:{zh:"以火枪战术统一日本中部，1573 年驱逐末代足利将军，1582 年在京都本能寺遭家臣明智光秀袭击自尽。",en:"Used firearms to conquer central Japan, ended the Ashikaga shogunate in 1573 and died in 1582 when his vassal Akechi Mitsuhide attacked him at Honnō-ji in Kyoto."}},
{id:"toyotomi-hideyoshi",y:[1537,1598],at:["osaka","kyoto"],n:{zh:"丰臣秀吉",en:"Toyotomi Hideyoshi"},r:{zh:"日本统一者",en:"Unifier of Japan"},d:{zh:"足轻出身，继承织田信长事业统一日本，修筑大阪城，两次出兵朝鲜。",en:"Rose from the ranks to complete Nobunaga’s unification of Japan, built Osaka Castle and twice invaded Korea."}},
{id:"yi-sun-sin",y:[1545,1598],at:["seoul"],n:{zh:"李舜臣",en:"Yi Sun-sin"},r:{zh:"朝鲜水军将领",en:"Korean admiral"},d:{zh:"壬辰战争中以龟船屡败日本水军，1598 年在露梁海战中阵亡。",en:"Defeated the Japanese navy again and again with his turtle ships in the Imjin War and was killed at the Battle of Noryang in 1598."}},
{id:"tokugawa-ieyasu",y:[1543,1616],at:["tokyo","osaka","kyoto"],c:[137.16,34.96],pl:{en:"Okazaki",zh:"冈崎"},n:{zh:"德川家康",en:"Tokugawa Ieyasu"},r:{zh:"江户幕府将军",en:"First Tokugawa shogun"},d:{zh:"关原之战获胜，1603 年在江户开创德川幕府，1615 年攻灭丰臣氏，此后日本和平两百余年。",en:"Won at Sekigahara, founded the Tokugawa shogunate at Edo in 1603 and destroyed the Toyotomi at Osaka in 1615, opening more than two centuries of peace."}},
{id:"emperor-meiji",y:[1852,1912],at:["tokyo","kyoto"],n:{zh:"明治天皇",en:"Emperor Meiji"},r:{zh:"日本天皇",en:"Emperor of Japan"},d:{zh:"在位期间幕府倒台，从京都迁居东京，日本推行明治维新，迅速工业化并对外扩张。",en:"Under him the shogunate fell, the court moved from Kyoto to Tokyo and Japan rapidly modernised and expanded in the Meiji Restoration."}},
// ---- South & South-East Asia ----
{id:"buddha",y:[-563,-483],ca:1,at:["varanasi","patna"],c:[83.28,27.48],pl:{en:"Lumbini",zh:"蓝毗尼"},n:{zh:"释迦牟尼",en:"Siddhartha Gautama, the Buddha"},r:{zh:"佛教创始人",en:"Founder of Buddhism"},d:{zh:"释迦族王子，出家修行后在菩提伽耶悟道，于瓦拉纳西郊外鹿野苑初转法轮。传统年代存在争议。",en:"Prince of the Shakya clan who renounced his life, reached enlightenment at Bodh Gaya and preached his first sermon at Sarnath near Varanasi. His dates are disputed."}},
{id:"chandragupta-maurya",y:[-340,-297],ca:1,at:["patna","taxila"],n:{zh:"旃陀罗笈多",en:"Chandragupta Maurya"},r:{zh:"孔雀王朝创建者",en:"Founder of the Maurya Empire"},d:{zh:"推翻难陀王朝，以华氏城为都，击退塞琉古一世，建立统一北印度的孔雀帝国。",en:"Overthrew the Nanda kings, ruled from Pataliputra, held off Seleucus I and founded the Maurya Empire across northern India."}},
{id:"ashoka",y:[-304,-232],ca:1,at:["patna","ujjain"],n:{zh:"阿育王",en:"Ashoka"},r:{zh:"孔雀王朝皇帝",en:"Maurya emperor"},d:{zh:"征服羯陵伽后痛悔杀戮，皈依佛教，在各地立石柱刻诏，并派人四方弘法。",en:"After the bloody conquest of Kalinga he turned to Buddhism, carved edicts on pillars and rocks across his empire and sent missionaries abroad."}},
{id:"anawrahta",y:[1014,1077],at:["bagan"],n:{zh:"阿奴律陀",en:"Anawrahta"},r:{zh:"蒲甘国王",en:"King of Pagan"},d:{zh:"统一缅甸的第一位国王，引入上座部佛教，开启蒲甘的建塔时代。",en:"First king to unite Burma, who brought Theravada Buddhism to Bagan and began its age of temple building."}},
{id:"jayavarman-vii",y:[1122,1218],ca:1,at:["angkor"],n:{zh:"阇耶跋摩七世",en:"Jayavarman VII"},r:{zh:"高棉国王",en:"Khmer king"},d:{zh:"击退占婆后重建吴哥，修建吴哥通王城与巴戎寺，信奉大乘佛教。",en:"Drove out the Cham, rebuilt Angkor with the walled city of Angkor Thom and the Bayon, and favoured Mahayana Buddhism."}},
{id:"krishnadevaraya",y:[1471,1529],at:["vijayanagara"],n:{zh:"克里希纳德瓦·拉亚",en:"Krishnadevaraya"},r:{zh:"毗奢耶那伽罗皇帝",en:"Emperor of Vijayanagara"},d:{zh:"毗奢耶那伽罗帝国最著名的君主，屡败德干诸苏丹国，宫廷文学繁荣，葡萄牙人留下了对其都城的记述。",en:"The most celebrated ruler of Vijayanagara, who defeated the Deccan sultanates and patronised literature; Portuguese visitors described his capital."}},
{id:"babur",y:[1483,1530],at:["kabul","agra","samarkand"],c:[72.79,40.38],pl:{en:"Andijan",zh:"安集延"},n:{zh:"巴布尔",en:"Babur"},r:{zh:"莫卧儿帝国创建者",en:"Founder of the Mughal Empire"},d:{zh:"帖木儿与成吉思汗的后裔，失去撒马尔罕后据有喀布尔，1526 年在帕尼帕特获胜，建立莫卧儿帝国；自传《巴布尔回忆录》传世。",en:"Descendant of Timur and Genghis Khan who lost Samarkand, ruled from Kabul and in 1526 won at Panipat to found the Mughal Empire; his memoirs survive."}},
{id:"akbar",y:[1542,1605],at:["agra","lahore","delhi"],n:{zh:"阿克巴",en:"Akbar"},r:{zh:"莫卧儿皇帝",en:"Mughal emperor"},d:{zh:"莫卧儿帝国最伟大的皇帝，扩张疆土，推行宗教宽容，建立高效的行政制度。",en:"The greatest Mughal emperor, who expanded the empire, practised religious tolerance and built an effective administration."}},
{id:"shah-jahan",y:[1592,1666],at:["agra","delhi","lahore"],n:{zh:"沙贾汗",en:"Shah Jahan"},r:{zh:"莫卧儿皇帝",en:"Mughal emperor"},d:{zh:"为纪念亡妻修建泰姬陵，营建德里红堡，晚年被儿子奥朗则布囚禁于阿格拉堡。",en:"Built the Taj Mahal for his late wife and the Red Fort in Delhi; in old age he was imprisoned in the Agra Fort by his son Aurangzeb."}},
{id:"aurangzeb",y:[1618,1707],at:["delhi","agra"],n:{zh:"奥朗则布",en:"Aurangzeb"},r:{zh:"莫卧儿皇帝",en:"Mughal emperor"},d:{zh:"在位期间莫卧儿版图最大，但长年征战德干与严苛的宗教政策削弱了帝国。",en:"Ruled the Mughal Empire at its largest, but decades of war in the Deccan and strict religious policies weakened it."}},
{id:"ranjit-singh",y:[1780,1839],at:["lahore"],n:{zh:"兰吉特·辛格",en:"Ranjit Singh"},r:{zh:"锡克帝国君主",en:"Maharaja of the Sikh Empire"},d:{zh:"1799 年攻取拉合尔，统一旁遮普，建立锡克帝国，为阿姆利则金庙贴金。",en:"Took Lahore in 1799, united the Punjab in the Sikh Empire and covered the Golden Temple at Amritsar with gold."}},
{id:"raffles",y:[1781,1826],at:["singapore","jakarta"],n:{zh:"斯坦福·莱佛士",en:"Stamford Raffles"},r:{zh:"英国殖民官员",en:"British colonial official"},d:{zh:"拿破仑战争期间管理爪哇，1819 年为东印度公司在新加坡建立商站。",en:"Governed Java during the Napoleonic Wars and in 1819 founded a trading post at Singapore for the East India Company."}},
{id:"chulalongkorn",y:[1853,1910],at:["bangkok"],n:{zh:"朱拉隆功（拉玛五世）",en:"Chulalongkorn (Rama V)"},r:{zh:"暹罗国王",en:"King of Siam"},d:{zh:"废除奴隶制、改革政府，在英法之间周旋，使暹罗保持独立。",en:"Abolished slavery, reformed the government and played Britain and France against each other to keep Siam independent."}},
{id:"tagore",y:[1861,1941],at:["kolkata"],n:{zh:"罗宾德拉纳特·泰戈尔",en:"Rabindranath Tagore"},r:{zh:"诗人",en:"Poet"},d:{zh:"加尔各答出生的孟加拉诗人，1913 年成为第一位获得诺贝尔文学奖的亚洲人。",en:"Bengali poet from Calcutta who in 1913 became the first Asian to win the Nobel Prize in Literature."}},
{id:"rizal",y:[1861,1896],at:["manila"],c:[121.17,14.21],pl:{en:"Calamba",zh:"卡兰巴"},n:{zh:"何塞·黎刹",en:"José Rizal"},r:{zh:"菲律宾民族英雄",en:"Filipino national hero"},d:{zh:"医生和作家，小说《不许犯我》揭露西班牙殖民统治，1896 年在马尼拉被处决。",en:"Doctor and novelist whose Noli Me Tángere exposed Spanish colonial rule; he was executed in Manila in 1896."}},
{id:"gandhi",y:[1869,1948],at:["mumbai","delhi"],c:[69.61,21.64],pl:{en:"Porbandar",zh:"博尔本德尔"},n:{zh:"甘地",en:"Mahatma Gandhi"},r:{zh:"印度独立运动领袖",en:"Leader of Indian independence"},d:{zh:"以非暴力不合作运动领导印度争取独立，1948 年在德里遇刺。",en:"Led India’s struggle for independence through non-violent resistance and was assassinated in Delhi in 1948."}},
{id:"jinnah",y:[1876,1948],at:["mumbai","lahore"],c:[67.01,24.86],pl:{en:"Karachi",zh:"卡拉奇"},n:{zh:"穆罕默德·阿里·真纳",en:"Muhammad Ali Jinnah"},r:{zh:"巴基斯坦国父",en:"Founder of Pakistan"},d:{zh:"在孟买执业的律师，领导全印穆斯林联盟，1947 年巴基斯坦建国后任首任总督。",en:"Bombay lawyer who led the All-India Muslim League and became Pakistan’s first governor-general in 1947."}},
{id:"nehru",y:[1889,1964],at:["delhi"],c:[81.85,25.44],pl:{en:"Allahabad",zh:"阿拉哈巴德"},n:{zh:"贾瓦哈拉尔·尼赫鲁",en:"Jawaharlal Nehru"},r:{zh:"印度首任总理",en:"First prime minister of India"},d:{zh:"国大党领袖，1947 年起任印度总理至去世，是不结盟运动的倡导者之一。",en:"Congress leader who served as India’s prime minister from 1947 until his death and was a founder of the Non-Aligned Movement."}},
{id:"ho-chi-minh",y:[1890,1969],at:["hanoi","saigon","hue"],n:{zh:"胡志明",en:"Ho Chi Minh"},r:{zh:"越南革命领袖",en:"Vietnamese revolutionary leader"},d:{zh:"1945 年在河内宣布越南独立，领导抗法与抗美战争；西贡在 1976 年以他的名字命名。",en:"Declared Vietnam’s independence in Hanoi in 1945 and led the wars against France and the United States; Saigon was renamed after him in 1976."}},
// ---- Africa ----
{id:"ezana",y:[320,360],ca:1,at:["axum","meroe"],n:{zh:"埃扎纳",en:"Ezana of Aksum"},r:{zh:"阿克苏姆国王",en:"King of Aksum"},d:{zh:"阿克苏姆第一位信奉基督教的国王，在钱币与碑铭上使用十字，曾远征麦罗埃。",en:"The first Christian king of Aksum, who put the cross on his coins and inscriptions and campaigned against Meroë."}},
{id:"mansa-musa",y:[1280,1337],ca:1,at:["timbuktu","gao","cairo","mecca"],n:{zh:"曼萨·穆萨",en:"Mansa Musa"},r:{zh:"马里帝国皇帝",en:"Emperor of Mali"},d:{zh:"1324 年赴麦加朝觐，途经开罗时大量散发黄金，使马里闻名于地中海世界；在廷巴克图修建清真寺。",en:"Made the pilgrimage to Mecca in 1324, spending so much gold in Cairo that Mali became famous around the Mediterranean; he built mosques in Timbuktu."}},
{id:"askia-muhammad",y:[1443,1538],ca:1,at:["gao","timbuktu"],n:{zh:"阿斯基亚·穆罕默德",en:"Askia Muhammad"},r:{zh:"桑海帝国皇帝",en:"Emperor of Songhai"},d:{zh:"夺取桑海王位后扩张帝国，推行伊斯兰行政改革，葬于加奥的金字塔形陵墓。",en:"Seized the Songhai throne, expanded the empire and reformed its government on Islamic lines; he is buried in the pyramid tomb at Gao."}},
{id:"nzinga",y:[1583,1663],ca:1,at:["luanda"],n:{zh:"恩津加女王",en:"Queen Nzinga"},r:{zh:"恩东戈与马坦巴女王",en:"Queen of Ndongo and Matamba"},d:{zh:"1622 年出使罗安达与葡萄牙人谈判，此后数十年领导抵抗葡萄牙殖民扩张。",en:"Negotiated with the Portuguese at Luanda in 1622 and for decades afterwards led resistance to their expansion."}},
{id:"osei-tutu",y:[1660,1717],ca:1,at:["kumasi"],n:{zh:"奥塞·图图",en:"Osei Tutu"},r:{zh:"阿散蒂帝国创建者",en:"Founder of the Asante Empire"},d:{zh:"以库马西为都联合阿肯诸邦，建立阿散蒂帝国；“金凳子”成为国家统一的象征。",en:"United the Akan states around Kumasi into the Asante Empire, with the Golden Stool as the symbol of the nation."}},
{id:"menelik-ii",y:[1844,1913],at:["addis","gondar"],n:{zh:"孟尼利克二世",en:"Menelik II"},r:{zh:"埃塞俄比亚皇帝",en:"Emperor of Ethiopia"},d:{zh:"建立亚的斯亚贝巴，1896 年在阿杜瓦击败意大利，使埃塞俄比亚保持独立。",en:"Founded Addis Ababa and defeated Italy at Adwa in 1896, keeping Ethiopia independent."}},
{id:"haile-selassie",y:[1892,1975],at:["addis"],n:{zh:"海尔·塞拉西一世",en:"Haile Selassie I"},r:{zh:"埃塞俄比亚皇帝",en:"Emperor of Ethiopia"},d:{zh:"1930 年加冕，意大利入侵期间流亡，1941 年复位，推动成立非洲统一组织，1974 年被推翻。",en:"Crowned in 1930, exiled during the Italian occupation and restored in 1941; he helped found the Organisation of African Unity and was overthrown in 1974."}},
{id:"kenyatta",y:[1897,1978],ca:1,at:["nairobi"],n:{zh:"乔莫·肯雅塔",en:"Jomo Kenyatta"},r:{zh:"肯尼亚首任总统",en:"First president of Kenya"},d:{zh:"肯尼亚民族主义领袖，茅茅起义期间被英国当局监禁，1964 年起任肯尼亚总统。",en:"Kenyan nationalist leader imprisoned by the British during the Mau Mau rising; he became president of Kenya in 1964."}},
{id:"nkrumah",y:[1909,1972],at:[],c:[-0.19,5.56],pl:{en:"Accra",zh:"阿克拉"},n:{zh:"克瓦米·恩克鲁玛",en:"Kwame Nkrumah"},r:{zh:"加纳首任总统",en:"First leader of Ghana"},d:{zh:"领导黄金海岸于 1957 年独立为加纳，成为撒哈拉以南第一个摆脱殖民统治的国家，倡导泛非主义。",en:"Led the Gold Coast to independence as Ghana in 1957, the first colony south of the Sahara to break free, and championed pan-Africanism."}},
{id:"mandela",y:[1918,2013],at:["johannesburg","capetown"],c:[28.78,-31.95],pl:{en:"Mvezo",zh:"姆维佐"},n:{zh:"纳尔逊·曼德拉",en:"Nelson Mandela"},r:{zh:"南非总统",en:"President of South Africa"},d:{zh:"反种族隔离运动领袖，在罗本岛等地坐牢二十七年，1994 年当选南非首位黑人总统。",en:"Leader of the struggle against apartheid who spent twenty-seven years in prison, much of it on Robben Island, and in 1994 became South Africa’s first black president."}},
// ---- Americas ----
{id:"pachacuti",y:[1418,1471],ca:1,at:["cusco"],n:{zh:"帕查库特克",en:"Pachacuti"},r:{zh:"印加皇帝",en:"Sapa Inca"},d:{zh:"击退昌卡人后即位，将库斯科小国扩张为印加帝国，重建库斯科并修建马丘比丘。",en:"Took power after defeating the Chanka, turned the small state of Cusco into the Inca Empire, rebuilt the capital and built Machu Picchu."}},
{id:"moctezuma-ii",y:[1466,1520],ca:1,at:["mexicocity"],n:{zh:"蒙特苏马二世",en:"Moctezuma II"},r:{zh:"阿兹特克皇帝",en:"Aztec emperor"},d:{zh:"阿兹特克帝国鼎盛时的统治者，1519 年接待科尔特斯，后被西班牙人扣押，在动乱中死去。",en:"Ruler of the Aztec Empire at its height who received Cortés in 1519, was held hostage by the Spanish and died in the fighting that followed."}},
{id:"cortes",y:[1485,1547],at:["mexicocity","seville"],c:[-5.96,38.97],pl:{en:"Medellín",zh:"梅德林"},n:{zh:"埃尔南·科尔特斯",en:"Hernán Cortés"},r:{zh:"西班牙征服者",en:"Spanish conquistador"},d:{zh:"1519 年率数百人登陆墨西哥，联合特拉斯卡拉等族于 1521 年攻陷特诺奇蒂特兰。",en:"Landed in Mexico in 1519 with a few hundred men and, allied with the Tlaxcalans and others, took Tenochtitlan in 1521."}},
{id:"pizarro",y:[1478,1541],ca:1,at:["lima","cusco"],c:[-5.88,39.46],pl:{en:"Trujillo, Spain",zh:"西班牙特鲁希略"},n:{zh:"弗朗西斯科·皮萨罗",en:"Francisco Pizarro"},r:{zh:"西班牙征服者",en:"Spanish conquistador"},d:{zh:"1532 年在卡哈马卡俘获印加皇帝阿塔瓦尔帕，征服印加帝国，建立利马，后在利马被政敌刺杀。",en:"Captured the Inca emperor Atahualpa at Cajamarca in 1532, conquered the Inca Empire and founded Lima, where rivals later killed him."}},
{id:"atahualpa",y:[1502,1533],ca:1,at:["quito","cusco"],n:{zh:"阿塔瓦尔帕",en:"Atahualpa"},r:{zh:"印加皇帝",en:"Sapa Inca"},d:{zh:"在内战中击败兄长瓦斯卡尔，刚成为印加皇帝就被皮萨罗俘虏，交付赎金后仍被处死。",en:"Defeated his brother Huáscar in civil war and had just become emperor when Pizarro captured him; he was executed despite paying a huge ransom."}},
{id:"champlain",y:[1574,1635],ca:1,at:["quebec","montreal"],n:{zh:"萨缪尔·德·尚普兰",en:"Samuel de Champlain"},r:{zh:"探险家",en:"Explorer"},d:{zh:"“新法兰西之父”，1608 年建立魁北克，绘制了圣劳伦斯河与五大湖地区的地图。",en:"The ‘Father of New France’, who founded Quebec in 1608 and mapped the St Lawrence and the Great Lakes."}},
{id:"sor-juana",y:[1648,1695],ca:1,at:["mexicocity"],n:{zh:"胡安娜·伊内斯·德拉克鲁斯修女",en:"Sor Juana Inés de la Cruz"},r:{zh:"诗人、学者",en:"Poet and scholar"},d:{zh:"新西班牙的修女与诗人，自学成才，捍卫女性求学的权利，被视为西班牙语巴洛克文学的代表。",en:"Nun and poet of New Spain, largely self-taught, who defended women’s right to learning and is a leading voice of Spanish Baroque literature."}},
{id:"franklin",y:[1706,1790],at:["boston","philadelphia","paris"],n:{zh:"本杰明·富兰克林",en:"Benjamin Franklin"},r:{zh:"科学家、政治家",en:"Scientist and statesman"},d:{zh:"生于波士顿，在费城从事印刷与电学研究，参与起草《独立宣言》，出使法国争取援助。",en:"Born in Boston, he printed and experimented with electricity in Philadelphia, helped draft the Declaration of Independence and won French support as envoy in Paris."}},
{id:"washington",y:[1732,1799],at:["philadelphia","washington","newyork"],c:[-76.94,38.19],pl:{en:"Westmoreland County, Virginia",zh:"弗吉尼亚威斯特摩兰县"},n:{zh:"乔治·华盛顿",en:"George Washington"},r:{zh:"美国首任总统",en:"First president of the United States"},d:{zh:"独立战争中任大陆军总司令，在约克镇迫使英军投降，1789 年就任首任总统。",en:"Commanded the Continental Army in the War of Independence, forced the British surrender at Yorktown and became the first president in 1789."}},
{id:"jefferson",y:[1743,1826],at:["philadelphia","washington","paris"],c:[-78.40,38.01],pl:{en:"Shadwell, Virginia",zh:"弗吉尼亚沙德韦尔"},n:{zh:"托马斯·杰斐逊",en:"Thomas Jefferson"},r:{zh:"美国第三任总统",en:"Third president of the United States"},d:{zh:"1776 年在费城起草《独立宣言》，任总统期间从法国购得路易斯安那。",en:"Drafted the Declaration of Independence in Philadelphia in 1776 and as president bought Louisiana from France."}},
{id:"tiradentes",y:[1746,1792],at:["ouropreto","rio"],n:{zh:"蒂拉登特斯",en:"Tiradentes"},r:{zh:"巴西独立运动先驱",en:"Forerunner of Brazilian independence"},d:{zh:"米纳斯密谋的成员，1792 年在里约热内卢被处决，今为巴西民族英雄。",en:"Member of the Minas conspiracy, executed in Rio de Janeiro in 1792 and now a national hero of Brazil."}},
{id:"san-martin",y:[1778,1850],at:["buenosaires","santiago","lima"],c:[-56.87,-29.06],pl:{en:"Yapeyú",zh:"亚佩尤"},n:{zh:"何塞·德·圣马丁",en:"José de San Martín"},r:{zh:"南美独立运动领袖",en:"Leader of South American independence"},d:{zh:"率安第斯军翻越安第斯山解放智利，1821 年在利马宣布秘鲁独立。",en:"Led the Army of the Andes across the mountains to free Chile and proclaimed Peru’s independence in Lima in 1821."}},
{id:"bolivar",y:[1783,1830],at:["caracas","bogota","quito","lima"],n:{zh:"西蒙·玻利瓦尔",en:"Simón Bolívar"},r:{zh:"南美独立运动领袖",en:"Liberator of South America"},d:{zh:"生于加拉加斯，领导委内瑞拉、哥伦比亚、厄瓜多尔、秘鲁和玻利维亚摆脱西班牙统治，被称为“解放者”。",en:"Born in Caracas, he led Venezuela, Colombia, Ecuador, Peru and Bolivia to independence from Spain and is known as El Libertador."}},
{id:"juarez",y:[1806,1872],at:["mexicocity"],c:[-96.47,17.21],pl:{en:"Guelatao, Oaxaca",zh:"瓦哈卡格拉陶"},n:{zh:"贝尼托·华雷斯",en:"Benito Juárez"},r:{zh:"墨西哥总统",en:"President of Mexico"},d:{zh:"萨波特克人出身的总统，推行自由主义改革，领导抵抗法国干涉，1867 年处决马克西米利安皇帝。",en:"Zapotec-born president who carried out liberal reforms, led resistance to the French intervention and had Emperor Maximilian executed in 1867."}},
{id:"lincoln",y:[1809,1865],at:["washington"],c:[-85.74,37.53],pl:{en:"Hodgenville, Kentucky",zh:"肯塔基霍真维尔"},n:{zh:"亚伯拉罕·林肯",en:"Abraham Lincoln"},r:{zh:"美国第十六任总统",en:"Sixteenth president of the United States"},d:{zh:"南北战争期间领导联邦，1863 年发表《解放奴隶宣言》和葛底斯堡演说，战争结束时在华盛顿遇刺。",en:"Led the Union through the Civil War, issued the Emancipation Proclamation and gave the Gettysburg Address in 1863, and was assassinated in Washington as the war ended."}},
{id:"pedro-ii",y:[1825,1891],at:["rio"],n:{zh:"佩德罗二世",en:"Pedro II of Brazil"},r:{zh:"巴西皇帝",en:"Emperor of Brazil"},d:{zh:"五岁即位，在位近五十年，1888 年巴西废除奴隶制，次年帝制被推翻。",en:"Became emperor at five and reigned for nearly fifty years; Brazil abolished slavery in 1888 and the monarchy fell the following year."}},
{id:"jose-marti",y:[1853,1895],at:["havana","newyork"],n:{zh:"何塞·马蒂",en:"José Martí"},r:{zh:"古巴诗人、独立运动领袖",en:"Cuban poet and independence leader"},d:{zh:"生于哈瓦那，长期流亡纽约组织古巴革命党，1895 年返回古巴参战阵亡。",en:"Born in Havana, he organised the Cuban Revolutionary Party in exile in New York and was killed in battle after returning to Cuba in 1895."}},
// ---- Oceania ----
{id:"abel-tasman",y:[1603,1659],at:["jakarta","hobart"],c:[6.60,53.25],pl:{en:"Lutjegast",zh:"吕特赫加斯特"},n:{zh:"阿贝尔·塔斯曼",en:"Abel Tasman"},r:{zh:"航海家",en:"Navigator"},d:{zh:"荷兰东印度公司航海家，1642 年从巴达维亚出发，成为第一个到达塔斯马尼亚和新西兰的欧洲人。",en:"Dutch East India Company navigator who sailed from Batavia in 1642 and became the first European to reach Tasmania and New Zealand."}},
{id:"james-cook",y:[1728,1779],at:["sydney","honolulu","wellington"],c:[-1.24,54.56],pl:{en:"Marton, Yorkshire",zh:"约克郡马顿"},n:{zh:"詹姆斯·库克",en:"James Cook"},r:{zh:"航海家",en:"Navigator"},d:{zh:"三次太平洋航行，绘制新西兰海图，登陆澳大利亚东海岸植物学湾，1779 年在夏威夷被杀。",en:"Made three Pacific voyages, charted New Zealand, landed at Botany Bay on Australia’s east coast and was killed in Hawaiʻi in 1779."}},
{id:"kamehameha-i",y:[1758,1819],ca:1,at:["honolulu"],n:{zh:"卡美哈梅哈一世",en:"Kamehameha I"},r:{zh:"夏威夷国王",en:"King of Hawaiʻi"},d:{zh:"1795 年征服瓦胡岛，1810 年统一夏威夷群岛，建立夏威夷王国。",en:"Conquered Oʻahu in 1795 and by 1810 had united the Hawaiian Islands as a single kingdom."}},
];
